COLLDATA("tadabburur","ur",[[390,"§القصص\ndeeds\nحق سے تکبر کرنے سے اللہ کی پناہ مانگئے.\nایک خط کے ذریعہ اس شخص کو خبردار کیجئے جو گناہ میں لوگوں کا پیشوا بنتا ہو اسے بتائیے کہ اسے اپنے عمل کا گناہ ملے گا اوراس کی پیروی کرنے والوں کا بھی گناہ ملے گا.\nاللہ سے دعا کیجئے کہ آپ خیر میں لوگوں کے پیشوا بنیں،شر میں لوگوں کے پیشوا بننے سے اللہ کی پناہ مانگئے.\nguid\nمومن اللہ کے وعدہ پر بھروسہ رکھتا ہے کہ وہ اپنے اطاعت گزاروں کو بہترین نتیجہ سے نوازیگا.\nظلم کرنے سے بچئے کہ ظالموں کا انجام نقصان ہی ہوتاہے.\nظالموں کا انجام تباہی اور ہلاکت ہے.\nrefl\nفَلَمَّا جَآءَهُم مُّوسَىٰ بِـَٔايَٰتِنَا بَيِّنَٰتٖ قَالُواْ مَا هَٰذَآ إِلَّا سِحۡرٞ مُّفۡتَرٗى وَمَا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ ٣٦\n(وما سمعنا بہذا) اس کے بارے میں تو ہم نے سنا ہی نہیں۔ یعنی وہ رسالت جس کا تم اللہ کی طرف سے لانے کا دعویٰ کررہے ہو (فی آبائنا)اپنے باپ دادا کی زندگیوں میں۔ انہوں نے دراصل یہ کہہ کر اس بدعت کی طرف اشارہ کیا ہے جس نے بہت سے لوگوں کو گمراہ کرکے رکھ دیا اور وہ بدعت ہے ’’تقلیدی رسم ورواج کو دلیل بنانا‘‘ خاص کر اس کے زیادہ قدیم ہونے کی وجہ سے۔ (البقاعی: ۱۴؍۲۹۲)\nبدعتی اپنی بدعت کو ثابت کرنے کے لئے اکثر کون سی دلیل دہراتے رہتے ہیں؟\nوَقَالَ فِرۡعَوۡنُ يَٰٓأَيُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَٰهٍ غَيۡرِي فَأَوۡقِدۡ لِي يَٰهَٰمَٰنُ عَلَى ٱلطِّينِ فَٱجۡعَل لِّي صَرۡحٗا لَّعَلِّيٓ أَطَّلِعُ إِلَىٰٓ إِلَٰهِ مُوسَىٰ وَإِنِّي لَأَظُنُّهُۥ مِنَ ٱلۡكَٰذِبِينَ ٣٨\nتعجب ہے قوم کے ان سربراہوں پر جنہیں اپنے بڑے پن کا بڑا گمان تھا کہ کیسے یہ شخص ان کی عقلوں سے کھیلتا اور انہیں بے وقوف بناتا تھا!؟ یہ دراصل ان کے فسق وفجور کی وجہ سے تھا جس کی گہرائی میں وہ ڈوبے ہوئے تھے جس سے پہلے ان کا دین فاسد ہوا پھر ان کی عقلیں بربادہوکر رہ گئیں۔ (السعدی؍ ۶۱۶)\nقوم فرعون کی عقلیں کیسے خراب ہوگئیں؟\nفَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلظَّٰلِمِينَ ٤٠\nاے محمد صلی اللہ علیہ وسلم!آپ دل کی نگاہوں سے ان پر غور فرمائیے کہ ان ظالموں کا معاملہ کس قدر سنگین تھا کہ پہلے انہوں نے اپنے رب کا انکا رکیا،پھر اس کے رسول کی نصیحت کو ٹھکرادیا۔تو کیا ہم انہیں ہلاک کرکے ان کے گھر باراور مال ودولت کا مالک اپنے نیک بندوں کو نہ بنادیں! (الطبری: ۱۹؍۵۸۲)\nاللہ تعالیٰ نے نبی صلی اللہ علیہ وسلم کو فرعون اور اس کے لشکر کے انجام ِہلاکت پر غوروفکر کرنے کا حکم دیا ہے حالانکہ آپ صلی اللہ علیہ وسلم کو ان ظالموں کے زمانہ میں رہ کر ان کی صحبت نہیں ملی تھی۔ اسے واضح کیجئے.\nوَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ ٤١\n(أئمة یدعون إلی النار) یعنی وہ لوگوں کو کفر کی طرف دعوت دیتے ہیں جو جہنم کا موجب ہے۔ (ابن جزی: ۲؍ ۱۴۳)\nایک انسان جہنم کا داعی کیسے بن جاتاہے؟\nوَجَعَلۡنَٰهُمۡ أَئِمَّةٗ يَدۡعُونَ إِلَى ٱلنَّارِۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ لَا يُنصَرُونَ ٤١\nیعنی ہم نے انہیں ایسا سربراہ بنادیا ہے جن کی اتباع کفر میں کی جاتی ہے۔اسی لئے ان پر ان کے پیروکاروں کا بھی گناہ ہوگا۔یہاں تک کہ ان کی سزا زیادہ ہوجائیگی۔ یہ بھی کہاگیا ہے کہ فرعون کی قوم کے بڑے لوگوں کو اللہ تعالیٰ نے نچلے طبقوں کا سردار بنادیا تھا،وہی انہیں جہنم کی طرف بلاتے تھے۔ اور یہ بھی کہا گیا ہے کہ وہ ایسے پیشوا ہیں جن کی اقتدا برے انجام سے دوچار ہونے والے کرتے ہیں اور عقلمندی وبصیرت والے ان سے نصیحت پکڑتے ہیں۔ (القرطبی: ۱۶؍۳۳۰)\nواضح کیجئے کہ وہ کیسے کفر کے سربراہ تھے؟\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَآئِرَ لِلنَّاسِ وَهُدٗى وَرَحۡمَةٗ لَّعَلَّهُمۡ يَتَذَكَّرُونَ ٤٣\nیقیناً یہ اللہ تعالیٰ کی سنت رہی ہے کہ نزول تورات سے پہلے جب کسی نبی کو جھٹلایا جاتا تھا تو اللہ تعالیٰ ان جھٹلانے والوں کو اپنے عذاب سے دوچار کردیتا تھا جس طرح کہ قوم ِنوح کو پانی میں ڈبو کر،قوم ہود کو تیز آندھی کے ذریعہ،قوم صالح کو سخت چیخ کے ذریعہ،قوم شعیب کو سائے والی بدلی کے ذریعہ،قوم لوط کو پتھروں کی بارش کے ذریعہ اور قوم ِ فرعون کو سمندر میں ڈبوکر ہلاک کردیا۔(ابن تیمیہ: ۵؍۸۰)\nگناہ گار قوموں کو اللہ تعالیٰ نے مختلف قسم کے عذاب سے ہلاک کیا۔ ان میں سے پانچ طرح کے عذاب کا ذکر کریں.\nوَلَقَدۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ مِنۢ بَعۡدِ مَآ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ\nیہ آیت اس بات کی دلیل ہے کہ نزول تورات کے بعد عام عذاب کے ذریعہ ہلاکت کا سلسلہ ختم ہوگیا اور کافروں سے تلوار کے ذریعہ جہاد کرنا مشروع ہوگیا۔ (السعدی؍۶۱۷)\nفرعون اور اس کی قوم کی ہلاکت کے بعد کیا کسی اور قو م کو عام عذاب کے ذریعہ ہلاک کیا گیا ہے؟\nwords\nمُفتَرىًگھڑا ہو؛ وہ جھوٹ جسے اللہ تعاليٰ کی طرف منسوب کیا جائے.\nعَاقِبَةُ الدَّارِآخرت میں اچھا انجام.\nصَرحًااونچی عمارت.\nفَنَبَذنَاهُم فِي اليَمِّہم نے اس کو پھینک دیا/ سمندر میں غرق کردیا.\nأَئِمَّةًجہنم کی طرف رہنمائی کرنے والے قائدین.\nوَأَتبَعنَاهُمہم نے ان کوملا دیا.\nالمَقبُوحِينَدور پڑے/ جن کے کام برے ہوں.\nبَصَائِرَ لِلنَّاسِان کے دلوں کا نور جس سے وہ حقائق کو دیکھ سکیں."],[391,"§القصص\ndeeds\nقرآن میں بیان کئے ہوئے قصوں میں سے کوئی قصہ چن کر اسے تفسیر یا تاریخ کی کتابوں میں پڑھئے؛کیونکہ ان قصوں میں بہت سی عبرتیں اور نصیحتیں ہیں.\nکسی ایسے عمل پر غورکیجئے جس میں آپ نے خواہش ِنفس کو اللہ کی شریعت پر ترجیح دی ہو،پھر اللہ سے استغفار کیجئے او ر اب شریعت کو خواہش پر مقدم رکھئے.\nخواہش ِنفس کی پیروی اور ہدایت کے بعد گمراہ ہوجانے سے اللہ کی پناہ مانگئے.\nguid\nاپنے ایمان اور علم کو باربار جانچنا اور ان کو یاد کرتے رہنا بہت ضروری ہے اس لئے کہ عمر بڑھنے اور وقت گزرنے کے ساتھ بہت سی باتیں بھول جاتی ہیں.\nمسلمان صحیح شرعی دلیل کو کافی سمجھ کر مطمئن ہوجاتا ہے.\nجان لیجئے کہ کتاب اللہ سے زیادہ ہدایت والی کتاب کوئی نہیں ہے.\nrefl\nوَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِيِّ إِذۡ قَضَيۡنَآ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّٰهِدِينَ ٤٤\n(وَمَا كُنتَ بِجَانِبِ الغربی)آپ اس وقت مغربی جانب نہیں تھے۔ یہ خطاب ہمارے نبی محمد صلی اللہ علیہ وسلم سے ہے لیکن اس سے مراد موسیٰ علیہ السلام کے بارے میں خبر دے کر صرف حجت قائم کرناہے۔آپ گرچہ اس وقت حاضر نہیں تھے۔ اور (الغربی)سے مرادطور پہاڑکے مغرب میں واقع وہ جگہ ہے جہاں اللہ تعالیٰ نے موسیٰ علیہ السلام سے کلام کیا تھا اور وہیں انہیں نبوت سے سرفراز کیا تھا۔ اور (من الشاہدین)سے مراد وہاں موجود لوگ ہیں ہے۔ یعنی آپ صلی اللہ علیہ وسلم وہاں حاضر نہیں تھے،ان غیب کی باتوں کو جاننے کے لئے جن کے بارے میں آپ کو بتایا جارہا ہے۔یہ سب آپ کو اللہ کی طرف سے وحی کے ذریعہ پتہ چل رہا ہے چنانچہ لوگوں کو چاہئے کہ آپ صلی اللہ علیہ وسلم پر ایمان لانے میں جلدی کریں۔ (ابن جزی: ۲؍ ۱۴۵)\nموسیٰ علیہ السلام کے واقعہ سے یہ کیسے پتہ چلتاہے کہ یہ کتاب اللہ کی جانب سے ہے اور یہ کہ محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں؟\nوَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ ٤٥\nعلم ختم ہوگیا اورآیات ِالٰہی کو بھلادیا گیا۔ ہم نے ایسے وقت میں آپ صلی اللہ علیہ وسلم کو مبعوث کیا جب آپ کی سخت ضرورت تھی اور اس علم کی سخت حاجت تھی جو ہم نے آپ کو عطا کیا اور آپ کی طرف وحی کیا۔ (السعدی؍ ۶۱۷)\nلوگوں کودین کی طرف بلانے اور تعلیم دینے والے داعی کی ضرورت کب شدید ہوجاتی ہے؟\nوَلَٰكِنَّآ أَنشَأۡنَا قُرُونٗا فَتَطَاوَلَ عَلَيۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِيٗا فِيٓ أَهۡلِ مَدۡيَنَ تَتۡلُواْ عَلَيۡهِمۡ ءَايَٰتِنَا وَلَٰكِنَّا كُنَّا مُرۡسِلِينَ ٤٥\nیعنی اللہ تعالیٰ نے محمد صلی اللہ علیہ وسلم کی ذات مبارکہ او ر آپ پر ایمان لانے کے بارے میں موسیٰ علیہ السلام اور ان کی قوم سے عہد وپیمان لیا تھا لیکن ایک لمبی مدت گزرجانے اورکئی صدیاں بیت جانے کے بعد وہ ان وعدو ں کو بھول گئے اور انہیں پورا نہیں کیا۔ (البغوی: ۳؍ ۴۴۳)\nلمبی مدت بیت جانے کی وجہ سے موسیٰ علیہ السلام کی قوم کیا چیز بھلا بیٹھی؟\nوَلَوۡلَآ أَن تُصِيبَهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ\nیعنی ان کے کفر ومعاصی کے ارتکاب کی وجہ سے ان پر مصیبتیں آئیں۔ ہاتھوں سے گرچہ ہر عمل کا ارتکاب نہیں کیا جاتا ہے البتہ اکثر اعمال ہاتھوں سے ہی انجام پاتے ہیں۔اسی وجہ سے ہر عمل کے ارتکاب کی نسبت ہاتھوں کی طرف کردی جاتی ہے۔ (الالوسی: ۱۰؍۲۹۷)\nہاتھ اللہ کی طرف سے ایک نعمت اور خیر وشر ہر طرح کے اعمال انجام دینے کا ایک وسیلہ ہے۔اس کی وضاحت کیجئے.\nفَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥٠\nیہ آیت اس بات پر دلیل ہے کہ جو رسول اللہ صلی اللہ علیہ وسلم کی بات نہ مان کر دوسرے کی پیروی کرے تو یقینا ًوہ ہدایت پر نہیں ہے بلکہ وہ خواہشات ِنفس کی طرف گامزن ہے۔ (حوالہ ؟)\nآیت کے اندر مذکور اتباع خواہشات کی کیا علامت ہے؟\nفَإِن لَّمۡ يَسۡتَجِيبُواْ لَكَ فَٱعۡلَمۡ أَنَّمَا يَتَّبِعُونَ أَهۡوَآءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥٠\nخواہشات؛ بلا علم نفس کے ارادوں کو کہتے ہیں۔ چنانچہ بلا علم ذاتی مصلحت کی خاطر نفس کے ارادوں پر چلنے والا خواہشات نفس کی پیروی کرنے والا کہلائیگا اور وہ علم جس کی بنیادپر بندہ اخروی مصلحت پرعمل پیرا ہوتا ہے،یہ وہی علم ہے جو تمام رسول علیہم السلام لے کر آئے۔ (ابن تیمیہ: ۵؍۸۳)\nاہل ِباطل جن خواہشات پر چلتے ہیں،ان سے کون سی خواہشات مراد ہیں؟\nوَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَيۡرِ هُدٗى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ٥٠\nنجات کے بارے میں غوروفکر اور اس کی پرواہ کئے بغیر خواہشات نفس کی پیروی کرنے والا بلا تحدید اکثر حالتوں میں نقصان اٹھانے والا ہوتاہے۔ (ابن عاشور: ۲۰؍۱۴۱)\nکیا وجہ ہے کہ خواہشات نفس کی پیروی کرنے والے سے زیادہ گمراہ کوئی نہیں ہوتا؟\nwords\nالغَربِيِّمغرب کی جانب.\nقَضَينَاہم نے عہد لیا.\nأَنشَأنَاہم نے پیدا کیا.\nفَتَطَاوَلَ عَلَيهِمُ العُمُرُوہ ایک لمبا زمانہ رہے.\nثَاوِيًامقیم ہوکر."],[392,"§القصص\ndeeds\nاپنے مال کا کچھ حصہ اللہ کے راستہ میں خرچ کیجئے.\nوعظ ونصیحت کی کسی مجلس میں شریک ہوئیے اور پوری دلجمعی سے بغور سنئے.\nبذریعہ پیغام لوگوں کو معمولات زندگی میں فضول خرچی اور گھمنڈ سے خبردار کیجئے،انہیں بتائیے کہ یہ زوال نعمت کے اسباب میں سے ہیں اوراس آیت کو بطور دلیل ذکر کیجئے.\nguid\nاہل ِکتاب کی فضیلت کا بیان جب کہ وہ نبی امی صلی اللہ علیہ وسلم اور قرآن کریم پر ایما ن لے آئیں اور اپنے آپ کو اللہ کے تابع کردیں.\nاس شخص کی فضیلت جو برائی کا جواب بھلائی سے دیتا ہے اور اللہ کا دیا ہوا رزق اس کی رضا کے لئے خرچ کرتاہے.\nاپنی گفتگو کو فحش اور دل آزار باتوں سے محفوظ رکھئے حتی کہ گنہگاروں کے ساتھ بات کریں تب بھی.\nrefl\n۞وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ يَتَذَكَّرُونَ ٥١\nپے درپے قرآن کو نازل کرنے کی بہت ساری حالتیں ہیں:الفاظ کے اعتبار سے تھوڑا تھوڑا نازل ہوا،یکبارگی نہیں اتر گیا۔ البتہ معانی کے اعتبار سے کلام کی مختلف شکلیں پہنچی ہیں جیسے وعد ووعید،ترغیب وترہیب،قصے،مواعظ اور عبر ت ونصیحتیں۔جو یکے بعد دیگرے پہنچتے رہے ہیں۔اور ان میں سے ہر ایک غوروفکر ا ورتدبر کے واسطے ذہن کو حاضر وچست رکھنے میں معاون ومددگار ہے۔ (ابن عاشور: ۲۰؍۱۴۲)\nقرآن کریم کے پے درپے ہونے کی حالتیں بیان کیجئے.\nوَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ\nبقولِ بعض برائیوں کو دور کرکے اور ان کے بدلے میں خوش گفتاری اختیار کرکے ان کا جواب دیتے ہیں۔اور بقول ِبعض توبہ واستغفار کے ذریعہ گناہوں کو دفع کردیتے ہیں۔ اس طور پر پہلے معنی کے اعتبار سے یہ مکارم ِاخلا ق کی صفت ہوگی یعنی جو اُن سے بری بات کہتے ہیں تو وہ اسے اچھی بات کہہ کر ٹال دیتے ہیں۔ (القرطبی: ۱۶؍۲۹۶)\nنیکی کے ذریعہ برائی کو کیسے دفع کیا جاسکتا ہے؟\nوَإِذَا سَمِعُواْ ٱللَّغۡوَ أَعۡرَضُواْ عَنۡهُ وَقَالُواْ لَنَآ أَعۡمَٰلُنَا وَلَكُمۡ أَعۡمَٰلُكُمۡ سَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ ٥٥\n(لا نبتغی الجاہلین) یعنی ہم جاہلوں سے نہیں الجھتے۔ ان کی یہ بات کس قدر صریح اور اچھی ہے! اس سے ان کے اخلاق کا پتہ چلتاہے کہ وہ علم اور عمدہ اخلاق کے طلبگار ہیں۔ (ابن عاشور: ۲۰؍۱۴۶)\nاہل ِکتاب میں سے جو لوگ قرآن پر ایمان لے آئے ان کی یہ بات(لا نبتغی الجاہلین)کس چیز کی طرف اشارہ کرتی ہے؟\nسَلَٰمٌ عَلَيۡكُمۡ لَا نَبۡتَغِي ٱلۡجَٰهِلِينَ ٥٥\n(سلام علیکم) سلامتی ہو تم پر۔ یہاں اس جملہ سے مراد’’تحیۃ اور سلام‘‘ نہیں ہے بلکہ اس سے مراد ترک ِکلام اور دوری اختیار کرنا ہے۔یا یہ کہ جدائی اور دوری اختیار کرنے کا سلام مراد ہے۔ (لا نبتغی الجاہلین) ہم جاہلوں سے نہیں لگتے یعنی ان سے باتوں میں تکرار اور بحث ومباحثہ نہیں چاہتے۔ (ابن جزی: ۲؍۱۴۷)\nباطل اور لہو ولعب کی مجلس میں ہوں تو ایک مسلمان کو کیا کرنا چاہئے؟\nإِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ ٥٦\nکہتے ہیں کہ وہ ہدایت جو دلوں میں ہوتی ہے وہ اللہ کے علاوہ کسی کے بس کی بات نہیں ہے۔لیکن بندہ اس کے اسباب پر قادر ہے اور اللہ تعالیٰ کے قول:(اہدنا الصراط المستقیم)، سے یہی مطلوب ہے۔اور (إنک لا تہدی من أحببت)کے ذریعہ رسول اللہ صلی اللہ علیہ وسلم سے اسی ہدایت کی نفی کی گئی ہے۔(ابن تیمیہ: ۵؍۸۷)\nاُ س ہدایت سے کیا مراد ہے جس کا مالک صرف اللہ تعالیٰ ہی ہے؟\nوَقَالُوٓاْ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَآۚ أَوَ لَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنٗا يُجۡبَىٰٓ إِلَيۡهِ ثَمَرَٰتُ كُلِّ شَيۡءٖ رِّزۡقٗا مِّن لَّدُنَّا وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ٥٧\nایمان لانے کی صورت میں اچک لئے جانے کے خوف کی کوئی وجہ نظر نہیں آتی کیونکہ جب بت پرستی کے باوجود انہیں اس کا خوف نہیں ہے تو وہ ایمان لانے کے بعد کیسے خوف میں مبتلا ہوسکتے ہیں حالانکہ ایسی صورت میں انہیں مقام کی حرمت کے ساتھ ساتھ ایمان کی حرمت بھی حاصل ہوجاتی ہے۔ (الالوسی: ۱۰؍۳۰۵)\nہدایت اور شریعت ِالٰہی کی تابعداری میں ہی حقیقی اَمان ہے۔ اس کی وضاحت کیجئے.\nوَكَمۡ أَهۡلَكۡنَا مِن قَرۡيَةِۢ بَطِرَتۡ مَعِيشَتَهَاۖ فَتِلۡكَ مَسَٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِيلٗاۖ وَكُنَّا نَحۡنُ ٱلۡوَٰرِثِينَ ٥٨\nبستیوں میں ان کے اترانے کا مطلب یہ ہے کہ:فخر وگھمنڈ،عیش پرستی اور خوشحالی کے مزے میں اس قدر حد سے بڑھ گئے کہ انہوں نے بستیوں کو بگاڑکر رکھ دیا اور نعمتوں کا شکر ادا نہیں کیا بلکہ انہوں نے حیرت میں پڑے مدہوش شخص کی طرح نعمتوں کو حاصل کیا اسی لئے ان کی قدردانی نہیں کی۔(البقاعی: ۱۴؍۳۲۷)\nحد سے بڑھی ہوئی نعمتوں والی زندگی کب ہلاکت کا باعث بن جاتی ہے؟\nwords\nوَصَّلنَاہم نے جدا کیا/ ہم نے بیان کیا.\nمَرَّتَينِدو بار- اپنی کتاب پر ایمان کی وجہ سے اور قرآن پر ایمان کی وجہ سے.\nوَيَدرَأُونَوہ دور کرتے ہیں.\nنُتَخَطَّفقتل یا قیدی بنانے میں تیز رفتاری کی وجہ سے أچک لیے جائیں.\nبَطِرَت مَعِيشَتَهَاوہ اپنی زندگی میں سرکش بن گئے."],[393,"§القصص\ndeeds\nآج ستربار اللہ سے توبہ اور استغفار کیجئے.\nآپ دنیوی امور میں سے کوئی اہم کام کرنا چاہتے ہوں تو استخارہ کی نیت سے دورکعتیں پڑھئے اور یہ دعا پڑھئے: (اَللّٰهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيْمِ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَّامُ الْغُيُوبِ، اَللّٰهُمَّ إِنْ كُنْتَ تَعْلَمُ اَنَّ هٰذَا الْأَمْرَ، خَيْر لِيْ فِي دِيْنِيْ وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أو قال: عَاجِل أَمْرِى وَ آجِلِهٖ، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي، ثُمَّ بَارِكْ لِي فِيهِ، اَللّٰهُمَّ وَإِنْ كُنْتَ تَعْلَمُ اَنَّ هٰذَا الْأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي، أَوْ قَالَ: فِي عَاجِلِ أَمْرِي وَآجِلِهِ، فَاصْرِفْهُ عَنِّي وَاصْرِفْنِيْ عَنْهُ وَاقْدُرْ لِي الْخَيْرَ حَيْثُ كَانَ، ثُمَّ رَضِّنِي بِهِ) .\nاللہ تعالیٰ سے دعا کیجئے کہ آپ کے ظاہر اور باطن کی اصلاح فرمادے.\nguid\nدنیوی کھانے،کپڑے اور گھر آپ کو آخرت کی نعمتوں سے غافل نہ کردیں.\nقیامت کے دن برائی کے سردار اپنے متبعین سے براء ت ظاہر کریں گے.\nجب آپ کے پاس صحیح دلیل آجائے تو اس کی اتباع کیجئے اور اس پر عمل کیجئے اور یاد رکھئے اللہ تعالیٰ آپ سے پوچھنے والا ہے کہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کی دعوت کا کیا جواب دیا تھا.\nrefl\nوَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ٦٠\n(فمتاع الحیاة الدنیا وزینتہا) متاع ایسی چیزہے جس کی زیب وزینت سے چند ایام فائدہ اٹھالیا جائے۔لفظ ‘متاع’ سے قلت کا پتہ چلتاہے اور اس کے مقابلہ میں لفظ(أبقی) ہے جو دوام پر دلالت کرتا ہے۔جبکہ لفظ (الدنیا)سے قلت اور ذلت کا پتہ چلتاہے(وما عند اللہ) اللہ کے پاس یعنی جنت میں،مطلب ہے ثواب۔(خیر) یعنی یہ چیزفی نفسہ اُس سے بہتر ہے اس لئے کہ اس کی لذت خالص اور خوشگواری کامل ہوگی۔(وأبقی)اس کو بقا حاصل ہوگی کیونکہ وہ ابدی ہوگی۔اور زوال پذیر لازوال کے مقابل کیسے آسکتاہے! (أفلا تعقلون) یعنی غوروفکر کیوں نہیں کرتے!کہ ایسی چیز کا ارتکاب نہ کرتے کہ ایک بہتر چیز کے مقابلہ گھٹیا چیز بدلہ میں لے رہے ہو۔ (الالوسی: ۱۰؍۲۰۶)\nاس آیت سے آخرت کے مقابلہ میں دنیا کی حقارت کا پتہ چلتاہے۔ اس کی وضاحت کیجئے.\nوَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ٦٠\nیہ آیت کریمہ دلالت کرتی ہے کہ بندہ اپنی عقل کے مطابق آخرت کو دنیا پر ترجیح دیتا ہے اور اگر کوئی آخرت پر دنیا کو ترجیح دیتاہے تو اس کا باعث اس کی کم عقلی ہے۔ (السعدی؍۶۲۱)\nبے عقل اور عقلمند کو کیسے پہچانا جائیگا؟\nوَمَآ أُوتِيتُم مِّن شَيۡءٖ فَمَتَٰعُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَزِينَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَيۡرٞ وَأَبۡقَىٰٓۚ أَفَلَا تَعۡقِلُونَ ٦٠\nاس دنیا میں زیب وزینت کے جتنے بھی سامان تمہیں فراہم کئے گئے ہیں ان سے کہیں بہتر وہ نعمتیں ہیں جو اللہ کے فرمانبردار اور سچے بندوں کو جنت میں ملیں گی۔ (الطبری: ۱۹؍۶۰۴)\nدنیا کی اکثر نعمتیں کفار کے پاس کیوں ہیں؟\nقَالَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَٰٓؤُلَآءِ ٱلَّذِينَ أَغۡوَيۡنَآ أَغۡوَيۡنَٰهُمۡ كَمَا غَوَيۡنَاۖ تَبَرَّأۡنَآ إِلَيۡكَۖ مَا كَانُوٓاْ إِيَّانَا يَعۡبُدُونَ ٦٣\n(ربنا ہؤلاء)اس سے پیروکاروں کی طرف اشارہ ہے۔(الذین أغوینا) یعنی جنہیں ہم نے گمراہی میں ڈالا۔ یعنی ہم نے چکنی چپڑی اور گمراہ کن باتو ں کے ذریعہ انہیں گمراہ کیا اور انہوں نے اسے قبول کیا جبکہ وہ باتیں بالکل واضح طور پر غلط،بھونڈی اور شرمناک تھیں۔ہاں،ان کی وجہ سے ہمیں دنیوی مال ومتاع اور کچھ جاہ ومنصب ضرور حاصل ہوگیا۔ پھر وہ اپنی ان گمان کی باتوں کو دوبارہ پیش کریں گے جن سے انہیں چھٹکارے کی امید ہوگی اور کہیں گے: (أغویناہم )یعنی ہم نے انہیں گمراہی کی طرف بلایا تو وہ اپنے اختیار سے گمراہ ہوئے۔ (البقاعی: ۱۴؍۳۳۴)\nآیت کی روشنی میں بری صحبت اور کسی کی اندھی فرمانبرداری کی سنگینی واضح کیجئے.\nوَيَوۡمَ يُنَادِيهِمۡ فَيَقُولُ مَاذَآ أَجَبۡتُمُ ٱلۡمُرۡسَلِينَ ٦٥ فَعَمِيَتۡ عَلَيۡهِمُ ٱلۡأَنۢبَآءُ يَوۡمَئِذٖ فَهُمۡ لَا يَتَسَآءَلُونَ ٦٦\nیعنی خبریں ان سے اوجھل ہوجائیں گی۔ جب لوگوں کی خبریں معلوم نہ ہوسکیں تو کہتے ہیں: «قَدْ عَمِيَ عَنِّيْ خَبَرُ الْقَومِ» اور یہاں یہ تعبیر اس لئے لائی گئی کیونکہ دلیل اور حجت ان سے اوجھل ہوگئی تھی اور انہیں دلیلوں کا علم نہ ہوسکا اس لئے کہ اللہ تعالیٰ نے معذرت ان تک پہنچادی تھی اور ان پر حجت قائم کردی تھی۔پس ان کے پاس کوئی حجت باقی نہ رہی جسے وہ دلیل بناتے اور نہ کوئی خبر رہ گئی جسے وہ بتاتے کہ انہیں اس کے سبب نجات مل سکے۔(الطبری: ۱۹؍۶۰۷)\nگناہ گاروں کے پاس قیامت کے دن کوئی حجت باقی نہیں رہ جائیگی جسے وہ دلیل بناسکیں۔ایسا کیوں؟\nفَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَٰلِحٗا فَعَسَىٰٓ أَن يَكُونَ مِنَ ٱلۡمُفۡلِحِينَ ٦٧\n(عسی)یہ لفظ اللہ کی طرف سے وجوب کے لئے آتا ہے کیونکہ یہ اللہ کا فضل واحسان ہے جو لامحالہ ہوکر رہے گا۔ (ابن کثیر: ۳؍ ۳۸۳)\nلفظ (عسی ) جب اللہ کی طرف منسوب ہوتو کس بات کا فائدہ دیتاہے؟\nوَرَبُّكَ يَخۡلُقُ مَا يَشَآءُ وَيَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِيَرَةُۚ\nبعض علماء کا کہنا ہے: دنیوی معاملات میں کسی کام پر اقدام اس وقت تک نہیں کرنا چاہئے جب تک اس کے بارے میں اللہ سے استخارہ نہ کرلے۔اوروہ اس طرح کہ استخارہ کی نیت سے دورکعتیں نماز پڑھ لے۔(القرطبی: ۱۶؍۳۰۸)\nاپنے دنیوی معاملات میں آپ اللہ تعالیٰ سے استخارہ کیسے کریں گے؟\nwords\nأَغوَينَاہم نے انہیں گمراہی کی طرف بلایا؛ اورانہوں نے ہماری اتباع کی.\nفَعَمِيَتپس ان پر مخفی رہی.\nالخِيَرَةُاختیار."],[394,"§القصص\ndeeds\nاپنی حاصل کردہ کامیابیوں میں سے کسی کامیابی کو یاد کرکے اللہ تعالیٰ کے لئے تواضع کے ساتھ شکرانے کا سجدہ کیجئے.\nآج رات کو جلدی سونے اور صبح جلدی اٹھنے کی کوشش کیجئے کہ یہ اللہ کی نعمت کا شکرانہ اور فطرت کے قریب ہے.\nاپنی ماہانہ آمدنی کی فہرست بنائیے، جس میں اپنی دنیوی اور اخروی مصالح کے درمیان موازنہ کیجئے.\nguid\nحقیقی سننا تو دل کا سننا اورقبول کرنا ہے.\nیہ اللہ تعالیٰ کے شکر کی ادائیگی کا ایک ذریعہ ہے کہ دن کو طلب معاش میں مشغول رہا جائے اور رات کو آرام کیا جائے اور یہ سب اللہ کی رضاحاصل کرنے میں ہو، نہ کہ اس کے غضب کے موجب اعمال میں.\nجو آج یقین نہیں رکھتا اور ایمان نہیں لاتا وہ جب اللہ کے سامنے کھڑا ہوگا تب اس کی آنکھیں کھلیں گی.\nrefl\nقُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ ٧١\nاللہ کی وحدانیت پر استدلال کرنے کا بہت ہی انوکھا طریقہ اختیار کیا گیا ہے۔یہ عجیب کاریگری جو روزانہ دومرتبہ پیش آتی رہتی ہے جسے ہر باشعور آسانی سے سمجھ سکتاہے اورجو اس دنیا میں مظاہر فطرت کی تبدیلی کی سب سے واضح مظہر ہے۔ (ابن عاشور: ۲۰؍۱۶۸)\nاللہ کی وحدانیت کے لئے شب وروزکی تبدیلی سے کیوں استدلال کیا گیا ہے؟\nقُلۡ أَرَءَيۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَيۡكُمُ ٱلَّيۡلَ سَرۡمَدًا إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ مَنۡ إِلَٰهٌ غَيۡرُ ٱللَّهِ يَأۡتِيكُم بِضِيَآءٍۚ أَفَلَا تَسۡمَعُونَ ٧١\nان آیات کریمہ میں اس بات کی طرف اشارہ ہے کہ بندے کو چاہئے کہ وہ اللہ کی نعمتوں میں غوروفکر کرے، ان میں بصیرت حاصل کرے اور ان کے وجود اور ان کے عدم ِوجود کے درمیان موازنہ کرے کیونکہ جب وہ اللہ تعالیٰ کی نعمتوں کے وجود اور ان کے عدم وجود کے مابین موازنہ کریگا تو اس کی عقل کو اللہ کے احسان اور عنایت پر آگاہی حاصل ہوگی۔اس کے برعکس اگر کوئی یہ سمجھتا ہے کہ یہ ایسا معاملہ ہے جو ہمیشہ سے اسی طرح سے چلا آرہا ہے اور اسی طرح چلتا رہے گا اور اس کا دل اللہ تعالیٰ کی نعمتوں پر اس کی حمد وثناء سے خالی اور اس کی حقیقت کے دیدار سے بے بہرہ ہے کہ وہ ہر حال میں اللہ تعالیٰ کا محتاج ہے تو وہ ایسا شخص ہے جس کے دل میں کبھی ذکر اور شکر کا خیال پیدا نہیں ہوتا۔ (السعدی؍۶۲۳)\nمذکورہ آیتیں اللہ کی نعمتوں میں غوروفکر او ر تدبر کی ایک خاص حالت کی طرف اشارہ کرتی ہیں۔ وہ کیا ہے؟\nوَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ لِتَسۡكُنُواْ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ ٧٣\nاللہ تعالیٰ نے شب وروز کو تقسیم کرکے ایک کو سکون حاصل کرنے اور دوسرے کو چل پھر کر روزی تلاش کرنے کا ذریعہ بنادیا اور شب وروز کے تعلق سے اکثریت کا یہی حال ہے چنانچہ اسی اغلبیت کو دیکھ کر نعمتوں کو بیان کیا گیا۔ گرچہ ایسے لوگ بھی ملیں گے جو دن میں سکون حاصل کرتے او رراتوں میں روزی تلاش کرتے ہیں لیکن ایسا شاذونادر ہے،جس کا شمار نہیں ہوتا۔ (ابن عطیہ: ۴؍ ۲۹۷)\nاگر کوئی دن میں سوئے اور رات میں جاگے تو کیا وہ آیت کے مفہوم کے منافی ہے؟اس کی وضاحت کیجئے.\nإِنَّ قَٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَيۡهِمۡۖ\nجب اللہ تعالیٰ نے یہ فرمادیا: (وما أوتیتم من شیء فمتاع الحیاة الدنیا وزینتہا) یعنی جو کچھ بھی تمہیں دیا گیا وہ محض دنیوی مال ومتاع اور اس کی زیب وزینت ہے۔پھر اس کے بعد یہ بھی وضاحت کردی کہ قارون کواسی دنیاوی مال ومتاع سے نوازاگیا لیکن اس نے غرورکیا پھر وہ فرعون کی طرح اللہ کے عذاب سے نہ بچ سکا۔اور اے مشرکو!تم قارون اور فرعون سے نفری تعداد اور مال ومتاع کے اعتبار سے کسی طور بڑھ کر نہیں ہو، اس کے باوجود فرعون کو اس کی فوج اور مال ودولت نے کوئی فائدہ نہ دیا اوراسی طرح قارون کو موسیٰ علیہ السلام کی قرابت اور اس کے خزانے کوئی فائدہ نہ پہنچاسکے۔ (القرطبی: ۱۶؍۳۱۲)\nاس بات کی وضاحت کیجئے کہ اللہ تعالیٰ نے قارون کا قصہ یہاں کیوں بیان کیا،نیز اس سے کیا نصیحت ملتی ہے؟\nإِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡفَرِحِينَ ٧٦\n(لا تفرح)یہاں ’’فرح وسرور‘‘ سے مراد وہ خوشی ہے جو خودپسندی اور ظلم تک لے جائے۔اسی لئے اللہ تعالیٰ نے فرمایا: (إن اللہ لا یحب الفرحین)بےشک اللہ تعالیٰ اترانے والوں کو پسند نہیں کرتا۔اور یہ بھی کہاگیا کہ اس سے مراد دنیا پر خوش ہونا ہے کیونکہ دنیا پر وہی خوش ہوسکتاہے جو آخرت سے غافل ہو اور اس پر اللہ کا یہ قول دلالت کرتاہے: ﴿وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡ﴾ (سورۂ حدید: ۲۳) یعنی اللہ تعالیٰ نے جن نعمتوں سے تمہیں نواز رکھا ہے اس پر بہت خوش مت رہو۔ (ابن جزی: ۲؍ ۱۵۱)\nکس خوشی سے منع کیا گیا ہے؟\nوَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ وَأَحۡسِن كَمَآ أَحۡسَنَ ٱللَّهُ إِلَيۡكَۖ\nیعنی دنیا کے اپنے حصہ کو ضائع نہ کروبلکہ اس سے فائدہ اٹھاؤ اور ساتھ ہی آخرت کے لئے بھی عمل کرو۔ یہ بھی کہا گیا ہے کہ نیک اعمال کو چھوڑکر اپنی عمر ضائع نہ کرو کیونکہ دنیا میں انسان کا حصہ وہی اچھا عمل ہے جو وہ کرتا ہے۔ اس طورپر یہ کلام بطور وعظ اور نصیحت کے ہوگا۔ پہلے قول کے مطابق دنیا سے فائدہ اٹھانا جائزہوگا تاکہ آدمی نصیحت قبول کرنے سے منکر نہ ہو۔ (وأحسن کما أحسن اللہ إلیک) جس طرح اللہ تعالیٰ نے تمہیں مالدار بناکر تم پر احسان کیا اسی طرح تم بھی اللہ کے بندوں پر احسان کرو۔(ابن جزی: ۲؍۱۵۱)\nبندہ مال کے فتنہ سے کس طرح نجات پاسکتا ہے؟\nوَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ\nلفظ ’’نصیب’’ کو بندے کی ضمیر کی طرف اضافت کرنا اس بات پر دلالت کرتا ہے کہ ‘‘نصیب‘‘ اس کا حق ہے چنانچہ آدمی کا یہ حق ہے کہ وہ دنیا کے اندر اپنے مناسب حال کے مطابق اس سے فائدہ اٹھائے خاص طور سے ان چیزوں سے جو عبادات کا ذریعہ نہ ہو ں اور نہ وہ حرام ہوں۔ (ابن عاشور: ۲۰؍۱۷۹)\nکسی مسلمان کے لئے مناسب نہیں ہے کہ وہ گنجائش کے باوجود کھانے پینے میں تنگی کرے۔اس کی وضاحت کیجئے.\nwords\nسَرمَدًادائمی باقی.\nوَضَلَّاور وہ گمراہ ہوگیا/ چلا گیا.\nيَفتَرُونَو ہ جھوٹ گھڑتے ہیں.\nلَتَنُوءُ بِالعُصبَةِاس کا بوجھ ایک جماعت پر گراں ہو.\nوَابتَغِاور تلاش کر.\nوَلاَ تَنسَ نَصِيبَكَاور اپنا حصہ نہ چھوڑ."],[395,"§القصص\ndeeds\nجو لوگ ظاہری زیب وزینت سے دھوکہ میں پڑے ہوئے ہیں انہیں نصیحت کیجئے کہ دنیا کا مال و متاع فانی ہے اور انہیں قارون کا قصہ سنائیے.\nکسی محتاج مزدور کے ساتھ بیٹھئے،اس کی حاجتیں جانئے او ر اسے صدقہ دیجئے.\nدوسروں کے مقابلہ میں خود کو بڑا سمجھنے اور زمین میں فساد مچانے سے اللہ کی پناہ مانگئے.\nguid\nمادہ پرست دنیادار لوگ بہت جلد فتنوں میں مبتلا ہوجاتے ہیں.\nفتنہ کی شروعات ہوتی ہے تو علماء کے علاوہ کوئی اسے سمجھ نہیں پاتا۔ ہاں،جب ختم ہونے لگتا ہے توسب اسے جان لیتے ہیں.\nاللہ تعالیٰ کا فضل اور اس کی رحمت ہی ہے کہ وہ نیکیوں میں اضافہ کرتا ہے،گناہوں میں نہیں.\nrefl\nقَالَ إِنَّمَآ أُوتِيتُهُۥ عَلَىٰ عِلۡمٍ عِندِيٓۚ أَوَ لَمۡ يَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةٗ وَأَكۡثَرُ جَمۡعٗاۚ\nکیا وہ اس علم سے واقف نہ ہوسکا جو اسے فائدہ پہنچاتا اور یہ نہ جان سکا کہ اللہ تعالیٰ نے ان لوگوں کے ساتھ کیسا سلوک کیا جو حسی اور معنوی ہر اعتبار سے اس کے مقابلہ میں زیادہ طاقتور تھے اور وہ مال اور خدم و حشم سے گھرے رہتے تھے تاکہ اس چیز سے دھوکا نہ کھاتا جس سے وہ دھوکا کھاچکا۔ (الالوسی: ۱۰؍۳۲۶)\nجو اپنی ذات اور مال کے دھوکے میں پڑجائے اس کے بارے میں اللہ تعالیٰ کی کیا سنت رہی ہے؟\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ\n(وقال الذین أوتوا العلم) یعنی جنہیں دنیا وآخرت کے احوال کے بارے میں مناسب علم دیا گیا۔یہاں آخرت کا ثواب چاہنے والا بناکر پیش نہیں کیا گیا جو اس بات پر تنبیہ ہے کہ دنیا وآخرت کے احوال کا جاننا اس بات کا متقاضی ہے کہ حتمی طور پر پہلے سے اعراض کیا جائے اور دوسرے کی طرف متوجہ ہواجائے اور آرزو کرنے والوں کی آرزومحض اس بات پر دلالت کرتی ہے کہ انہیں دنیا وآخرت کے تعلق سے مناسب علم نہیں تھا۔ (الالوسی: ۱۰؍۳۲۷)\nجو جان بوجھ کر دنیا کی زیب وزینت سے اعراض کرکے آخرت کی طرف متوجہ ہو وہ فتنوں کے وقت دوسروں کے مقابلہ میں زیادہ ثابت قدم رہتا ہے۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ\nیہاں علم والے دنیوی زندگی چاہنے والوں پر بددعا نہیں کررہے ہیں اس لئے کہ نصیحت کا مقام نرم خطاب کا تقاضہ کرتاہے تاکہ نصیحت حاصل کرنے میں زیادہ معاون بن سکے۔البتہ یہ ان لوگوں پر تعجب کررہے ہیں جو دنیوی زیب وزینت میں پڑ ے ہوئے اور قارون کی حالت پر رشک کررہے ہیں،انہیں اللہ تعالیٰ کے اس ثواب کا کوئی خیال نہیں ہے جسے وہ دین پر عمل پیرا ہوکر اورفائدہ مندکام کرکے حاصل کرسکتے ہیں۔جبکہ ساتھ ہی انہیں یہ معلوم رہے کہ قارون دین واخلاق سے عاری ہے۔ (ابن عاشور: ۲۰؍۱۸۴)\nاہل علم نے: (ویلکم)سے کیا مراد لیا ہے؟\nوَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ ٨٠\nصبر کرنے والوں سے مراد وہ لوگ ہیں جنہوں نے دنیوی زندگی کی زیب وزینت پر صبر کیا اور دنیوی لذتوں اور شہوتوں کے بدلہ نیک اعمال کرکے اپنے رب کے پاس اجرعظیم کو ترجیح دی چنانچہ اللہ کی فرمانبرداری میں بڑھ چڑھ کر حصہ لیا اور دنیا پرستی سے دوررہے۔ (الطبری: ۱۹؍۶۲۹)\nفتنوں کے وقت ثابت قدمی کی توفیق کیسے ملتی ہے؟\nوَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ ٨٠\n(وَلا يُلَقَّاهَا) یعنی اہل ِعلم کی یہ باتیں اور نصیحتیں انہی کو حاصل ہوسکتی ہیں اور ان پر عمل وہی لوگ کرسکتے ہیں ﴿إِلَّا ٱلصَّٰبِرُونَ﴾ جو ہر خوشی وغمی میں اپنے رب کے فیصلوں پر صبر سے کام لیتے ہیں۔اطاعت وفرمانبرداری پر کاربندہوتے ہیں اور جو صبر کا پیکر ہوتے ہیں۔ اس لفظ کو جمع کے صیغہ کے ساتھ لانے کا مقصد آپسی تعاون پر ابھارنا ہے جس میں اس بات کی طرف اشارہ ہے کہ دینی امور میں پریشانیوں کی وجہ سے انہیں کوئی ایک شخص نہیں سنبھال سکتا۔ (البقاعی: ۱۴؍۳۵۸)\nصبر ایک عظیم اخلا ق ہے جس میں تعاون کی ضرورت ہے۔آیت اس معنی پر کیسے دلالت کرتی ہے؟\nفَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ\nقارون کی سزا اس کے عمل کے موافق تھی۔ جس طرح وہ اپنے آپ کو اللہ کے بندوں سے بلند سمجھتا تھا اسی طرح اللہ تعالیٰ نے اسے اس کے گھر اور مال ودولت سمیت جس نے اسے فریب میں مبتلا کررکھا تھا،انتہائی پستیوں میں اتار دیا۔(السعدی؍ ۶۲۴)\nقارون کو عذاب کی دوسری تمام قسمیں چھوڑکر زمین میں دھنساکر ہی کیوں عذاب دیا گیا؟\nتِلۡكَ ٱلدَّارُ ٱلۡأٓخِرَةُ نَجۡعَلُهَا لِلَّذِينَ لَا يُرِيدُونَ عُلُوّٗا فِي ٱلۡأَرۡضِ وَلَا فَسَادٗاۚ\nسورۂ قصص کی ابتداء فرعون کے قصہ اور زمین میں اس کی اُس بلندی سے ہوئی جسے اس نے سرداری،مقام ومرتبہ اور سلطنت سمجھ رکھاتھا۔پھر سورت کے آخر میں قارون کا قصہ ذکر کیا اور جو کچھ اسے مال ودولت سے نوازا گیا تھا۔ پھر دونوں میں سے ایک کی بادشاہت کا انجام او ر دوسرے کے مال ودولت کا انجام بتایا گیا پھر فرمایا: (تِلكَ الدَّارُ الآخِرَةُ نَجعَلُهَا لِلَّذينَ لا يُريدُونَ عُلُوًا فِي الأَرضِ وَلا فسَادًا) یعنی فرعون اور قارون کی طرح۔(ابن تیمیہ: ۵؍۹۰)\nسورۂ قصص کو اہل ِجنت کی ان دوصفتوں پر کیوں ختم کیا گیا کہ یہ لوگ زمین میں نہ تو بڑائی و فخر چاہتے ہیں اور نہ فتنہ وفساد؟\nwords\nالقُرُونِامتیں.\nوَلاَ يُسأَلُان سے جواب کے لیے سوال نہ ہوگا۔ بلکہ اقرار و توبیخ کے لیے ہوگا.\nوَيكَأَنَّتعجب اور افسوس کا کلمہ / تکلیف دینے والا کلمہ.\nوَيكَأَنَّهُکیا آپ نہیں جانتے کہ وہ.\nعُلُوًّاتکبر کرتے ہوئے."],[396,"§القصص ، العنكبوت\ndeeds\nہر جائز ذریعہ جو آپ کو مناسب لگے اسے اپناکر دعوت الی اللہ کا فریضہ انجام دیجئے.\nان کلمات سے اللہ سے دعا مانگئے: «اَللّٰهُمَّ يَا مُقَلِّبَ الْقُلُوْبِ ثَبِّتْ قَلْبِيْ عَلٰى دِيْنِكَ»۔اے اللہ!اے دلوں کے پھیرنے والے! میرے دل کو اپنے دین پر جمائے رکھ.\nوہ صحابہ کرام جو سخت تکلیفوں میں مبتلا کئے گئے جیسے کہ سلمان فارسی یا عمار بن یاسر وغیرہ ان میں سے کسی کا واقعہ پڑھئے اور دیکھئے کہ وہ کس طرح اپنے ایمان میں کھرے اترے اور صبر کیا.\nguid\nبرے ساتھی بہت خطرناک ہوتے ہیں اور اللہ کے راستہ سے روکنے کا سبب بنتے ہیں.\nبندے کو شرک سے ڈرتے رہناضروری ہے کیونکہ اللہ نے اپنے نبی صلی اللہ علیہ وسلم کو بھی غیر اللہ کی عبادت اور دعا کرنے سے منع کیا ہے ہمیں تو بدرجۂ اولی اس سے ڈرنا چاہئے.\nمجاہدہ کی اہمیت اور فضیلت کو بیان کیاگیا ہے کہ اسی میں نفس کی نجات او ر کامیابی ہے.\nrefl\nوَلَا يَصُدُّنَّكَ عَنۡ ءَايَٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَيۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ ٨٧\nیعنی تبلیغ ِدین میں آپ کو ان کی باتیں،ان کا جھوٹ اور ان کی ایذا رسانی بالکل نہ روکیں،آپ ان امور کی طرف بالکل دھیان نہ دے کر اپنے اس اہم کام اور ذمہ داری میں لگے رہیں۔ (القرطبی: ۱۴؍۳۳۰)\nہمت پست کرنے والی رکاوٹوں کے باوجود دعوت کے میدان میں کام کرتے رہنے پر یہ آیت کیسے دلالت کرتی ہے؟\nأَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ ٢\nکیا لوگوں نے یہ گمان کررکھا ہے کہ انہیں بغیر امتحان اور آزمائش کے چھوڑدیا جائیگا؟ (أن یقولوا) یعنی ان کے یہ کہنے پر کہ وہ ایمان لائے۔ (آمنا وہم لا یفتنون) یعنی ایمان لانے کے بعد کیا جان ومال میں ان کی آزمائش نہیں ہوگی؟ بالکل ہوگی تاکہ مخلص،منافق سے اورسچا،جھوٹے سے الگ ہوسکے۔ (البغوی: ۳؍ ۴۶۱)\nاللہ تعالیٰ اپنے بندوں کو کیوں آزماتا ہے؟\nأَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ ٢\nیہ آیت کریمہ مکہ میں موجود کمزور مومنوں کے بارے میں نازل ہوئی جنہیں اسلام لانے کی وجہ سے کفار قریش تکلیف دیتے تھے جس کی وجہ سے ان کے دل تنگ ہوگئے تھے چنانچہ اللہ تعالیٰ نے اس آیت کے ذریعہ انہیں تسلی دی اورنصیحت کرکے یہ خبر دی ہے کہ دراصل یہ آزمائش ہے تاکہ ایمان پر ثابت قدم رہیں اور تکلیفوں پر صبر کرنے میں مطمئن ہوجائیں۔پس اللہ نے انہیں باخبر کردیا کہ بندوں کے تعلق سے اس کی یہی سنت رہی ہے کہ کافروں کو مومنوں پر مسلط کرتا رہتا ہے تاکہ وہ مخلص بن جائیں اور سچا ایمان والا جھوٹے سے الگ ہوجائے۔یہاں لفظ عام ہے چنانچہ اس کا حکم بھی ہر اس شخص کے بارے میں عام ہوگا جو جان ومال کے نقصان اور مصائب کے فتنوں سے دوچار ہوا ہو۔ (ابن جزی: ۲؍ ۱۵۴)\nآیت کی روشنی میں ابتلاء وآزمائش کے فوائد بتائیے.\nوَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ ٣\nپہلے کے لوگوں سے مراد انبیاء سابقین کے وہ مومن پیروکار ہیں جو مختلف فتنوں اور آزمائشوں سے دوچار ہوئے تو صبر سے کام لیا اور مضبوطی سے اپنے دین پر جمے رہے جس طرح اللہ تعالیٰ کے اس فرمان سے بھی ظاہر ہوتا ہے: ﴿وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْ﴾ (سورۂ آل عمران: ۱۴۶)اور بہت سے انبیاء کے ساتھ اللہ والوں کی ایک بڑی تعداد نے جہاد کیا تو اللہ کی راہ میں ان کو جو تکلیف پہنچی اس کی وجہ سے نہ ہار مان لی اور نہ کمزور پڑے اور نہ دشمن سے دبے۔ (الالوسی: ۱۰؍ ۳۴۰)\nمومنوں کی آزمائش اللہ کی سنت میں سے ہے۔ایسے حالات میں ایک مومن پر کیا واجب ہوتاہے؟\nوَلَقَدۡ فَتَنَّا ٱلَّذِينَ مِن قَبۡلِهِمۡۖ فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ ٣\nیعنی آزمائش سے پہلے اللہ تعالیٰ ہی انہیں بہتر جانتاہے۔آیت کا مفہوم یہ ہے کہ اللہ تعالیٰ سچوں کو جھوٹوں سے ضرور ظاہر کردیگا یہاں تک کہ اس کا ازلی علم سامنے آجائے۔ (البغوی: ۳؍ ۴۶۲)\nیہ معلوم ہے کہ اللہ تعالیٰ کو ہر چیز کا علم ہے تو پھر یہاں (فلیعلمن اللہ) اللہ جان لے گا،کی کیا توجیہ ہوگی؟\nأَمۡ حَسِبَ ٱلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ أَن يَسۡبِقُونَاۚ\nجن کا ارادہ برے اعمال اور جرائم کا ارتکاب ہے،کیا انہوں نے یہ سمجھ رکھا ہے کہ ان کے اعمال کو یونہی چھوڑدیا جائیگا، اور اللہ تعالیٰ ان سے غافل رہے گا اور وہ اللہ تعالیٰ کی گرفت سے نکل بھاگیں گے اسی لئے وہ گناہوں کا ارتکاب کررہے ہیں اور ان کے لئے گناہوں کے کام کرنا آسان ہوگیا ہے۔ (السعدی؍ ۶۲۶)\nبندے کے لئے گناہوں اور جرائم کے ارتکاب کو کون سی چیز آسان بناتی ہے؟\nمَن كَانَ يَرۡجُواْ لِقَآءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَأٓتٖۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٥\nآیت کا مفہوم یہ ہے کہ جسے اللہ تعالیٰ کے ثواب کی امید ہو اسے چاہئے کہ وہ دنیا کے اندر اللہ کی فرمانبرداری میں مشقت اٹھاکر صبر کرے یہاں تک کہ قیامت کے دن اللہ سے ملاقات کرے جو اسے اس کا بدلہ عنایت کریگا کیونکہ اللہ تعالیٰ کی ملاقات قریب ہی آنے والی ہے۔ (ابن جزی: ۲؍۱۵۵)\nاللہ تعالیٰ کے ثواب کو حاصل کرنے کے لئے کیا شرط ہے؟\nwords\nفَرَضَاس نے نازل کیا.\nلَرَآدُّكَ إِلَى مَعَادٍضرور آپ کا ٹھکانہ وہی جگہ ہے جہاں سے آپ نکلے ہیں؛ یعنی مکہ.\nتَرجُوآپ امید کرتے ہیں.\nيُلقَىنازل کیا جاتا ہے.\nظَهِيرًامددگار.\nأَن يَسبِقُونَاوہ ہم سے بھاگ جائیں گے/ ہمیں عاجز کردیں گے."],[397,"§العنكبوت\ndeeds\nاپنے والدین کوکوئی ہدیہ دے کر ان کے ساتھ اچھاسلوک کیجئے.\nفتنوں کے موضوع پر کوئی کتاب پڑھئے.\nاپنے دوست کو نصیحت کیجئے کہ برائی پر مشتمل کوئی پیغام نہ بھیجے ورنہ جو بھی اس سے متاثر ہوگا اسے (بھیجنے والے کو)بھی اس کا گناہ ملے گا.\nguid\nاچھے کاموں میں والدین کی فرمانبرداری واجب ہے لیکن غلط کام جیسے کہ شرک یا اللہ کی نافرمانی تو ان میں ان کا حکم نہیں مانا جائیگا.\nاگر آپ کوئی گناہ کریں تو کسی دوسرے کو اس پر نہ ابھاریں ورنہ ڈر ہے کہ اس کا بھی گناہ آپ کے سر ہوگا.\nدعوت الی اللہ کے لئے محنت اور صبر کرنے میں انبیاء کرام علیہم السلام کی پیروی کرنی چاہئے.\nrefl\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَئِّاتِهِمۡ وَلَنَجۡزِيَنَّهُمۡ أَحۡسَنَ ٱلَّذِي كَانُواْ يَعۡمَلُونَ ٧\nیعنی ان کے اچھے اعمال کابہترین بدلہ دیں گے۔اس سے مراد اطاعت وفرمانبرداری ہے اور بقول بعض: ہم ان کے عمل سے کہیں زیادہ اور اچھا بدلہ دیں گے۔ (البغوی: ۲؍۴۶۳)\nاللہ تعالیٰ کے نزدیک مومنوں کو ان کے عمل سے بہتر بدلہ کیسے دیا جائیگا؟\nوَإِن جَٰهَدَاكَ لِتُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٞ فَلَا تُطِعۡهُمَآۚ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ ٨ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُدۡخِلَنَّهُمۡ فِي ٱلصَّٰلِحِينَ ٩\nادب کے اس مقام پر ایک لطیف مناسبت یہ ہے کہ شرک کا حکم دینے پر جب مومن کو والدین کی نافرمانی کے لئے کہا گیا جو کہ اس کے اور والدین کے بیچ اختلاف اور آپسی نفر ت کا سبب بن سکتا ہے تو اختلاف کی اس وحشت کے بدلے ایسی الفت ومحبت عطاکردی جس نے اسے نیک بندوں میں شامل کردیا جن سے وہ مانوس ہوگئے۔ (ابن عاشور: ۲۰؍۲۱۵)\nجو اللہ کی فرمانبرداری کو مخلوق کی فرمانبرداری پر مقدم کرتا ہے،اللہ تعالیٰ اس کی عزت واکرام میں اضافہ کرتاہے۔اس کی وضاحت کیجئے.\nوَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَآ أُوذِيَ فِي ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ\nیعنی لوگوں کی تکلیف اور ایذا کو آخرت میں اللہ کے عذاب کی طرح بناڈالا۔مطلب یہ کہ لوگوں کی تکلیف سے گھبراگیا،جزع فزع کرنے لگا اور صبر نہ کرسکا چنانچہ لوگوں کی اطاعت کربیٹھا،اسی طرح جیسے وہ شخص جو اللہ کے عذاب سے ڈر کر اس کی اطاعت کرتاہے۔(البغوی: ۳؍ ۴۶۴)\nلوگوں کے فتنہ کو ایک منافق کیسے عذاب ِالٰہی کی طرح سمجھ لیتا ہے؟\nوَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ\nاس آیت میں کفر وگمراہی کی طرف دعوت دینے والوں کے بارے میں خبر دی گئی ہے کہ قیامت کے دن یہ لوگ اپنے گناہوں کے بوجھ کے ساتھ ان لوگوں کے گناہوں کا بوجھ بھی اٹھائیں گے جن کو انہوں نے گمراہ کیا تھا جبکہ ان لوگوں کے بوجھ میں کوئی کمی نہیں آئیگی۔ (ابن کثیر: ۶؍۲۲۶)\nکیا فساد کی طرف بلانے والے کا گناہ بالکل اسی کی مانند ہوگا جس نے اس کی بات مانی تھی۔آیت کی روشنی میں اس کی وضاحت کیجئے.\nوَلَيَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالٗا مَّعَ أَثۡقَالِهِمۡۖ\nوہ گناہ جس کا ارتکاب کوئی تابع شخص کرتاہےاس میں تابع اور متبوع دونوں کا حصہ ہوتا ہے۔تابع کا حصہ اس لئے کہ اس نے اس گناہ کا ارتکاب کیا اور متبوع کا حصہ اس لئے کہ وہ اس گناہ کا سبب بنا اور اس نے اس گناہ کی طرف دعوت دی۔بالکل اسی طرح جب کوئی تابع شخص نیکی کرتا ہے تو اسے اس کا ثواب ملتا ہے اور وہ شخص بھی اس ثواب سے بہرہ ور ہوتاہے جس نے اسے نیکی کی دعوت دی اور نیکی کا سبب بنا۔ (السعدی؍ ۶۲۷)\nآیت میں بڑی باریکی سے دعوت دین کی طرف ابھارا گیا ہے۔ اس کی وضاحت کیجئے.\nوَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ ١٤\nسال کے لئے لفظ ’’عَام’’ کی بجائے ﴿سَنَةٍ﴾ کو اختیار کرنے میں باریکی یہ ہے کہ لفظ﴿سَنَةٍ﴾ سختی اور قحط پر دلالت کرتا ہے برخلاف لفظ‘‘عَام‘‘کے۔ اور چونکہ نوح علیہ السلام نے اپنی قوم کی طرف سے دعوت کے زمانہ میں بڑی تکلیفیں جھیلی تھیں اس لئے لفظ ﴿سَنَةٍ﴾ کا استعمال زیادہ مناسب ہوا۔ (الالوسی: ۱۰؍۳۴۸)\nاللہ کے فرمان﴿أَلۡفَ سَنَةٍ﴾میں لفظ ’’عَام‘‘کے ﴿سَنَةٍ﴾ سے تعبیر کرنے کے کیا فائدے ہیں؟\nوَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ ١٤\nاے محمد صلی اللہ علیہ وسلم! آپ اپنی قوم کے ان لوگوں پر بالکل افسوس نہ کریں جو کفر پر اڑے ہوئے ہیں اور نہ ان پر غم کریں؛کیونکہ اللہ ہی جسے چاہتا ہے ہدایت دیتا ہے اور جسے چاہتا ہے گمراہ کردیتا ہے،سارا معاملہ اسی کے ہاتھ میں ہے اور ساری چیزیں اسی کی طرف لوٹ کر جانے والی ہیں۔ (ابن کثیر: ۳؍۳۹۳)\nکیا ہدایت عقل کی بنیاد پر ملتی ہے یا اس کی کوئی اور وجہ ہے؟\nwords\nفِتنَةَ النَّاسِلوگوں کا اس کو تکلیف دینا۔ عذاب دینا.\nسَبِيلَنَاہمارا دین.\nأَثقَالَهُمان کے بوجھ.\nيَفتَرُونَوہ جھوٹ گھڑتے ہیں."],[398,"§العنكبوت\ndeeds\nاللہ سے دعا کیجئے کہ آپ کو روزی دے اور پھر اس کے حصول کے لئے جدوجہد کیجئے.\nصحیح بخاری میں ’’کتاب بدء الخلق‘‘ کی کچھ احادیث پڑھئے تاکہ اللہ تعالیٰ کی عظیم قدرت پر غورکرسکیں.\n(جائز حدود میں رہتے ہوئے) انسان کی تخلیق کے مراحل پر بنائی گئی کوئی ڈاکیومنٹری فلم یا تصویریں دیکھئے اور اپنی تخلیق کے مراحل اور اس کی اصل پر غور کیجئے.\nguid\nاللہ تعالیٰ ہی ہے جو محتاجگی دور کرتا اور روزی نازل کرتا ہے،اس کے علاوہ کوئی اس کا اختیار نہیں رکھتا لہذا ہم بلاواسطہ اسی سے مانگیں.\nیہ انسان کی ہر اعتبار سے مکمل عاجزی کا بیان ہےکہ وہ اللہ سے بھاگ کر کہیں نہیں جاسکتا اسے ایمان اور تقویٰ کے ساتھ اسی کی طرف پلٹ کر آنے کے سوا کوئی چارہ نہیں.\nاللہ کی رحمت سے مایوسی عذاب اور ہلاکت کے اسباب میں سے ہے.\nrefl\nفَأَنجَيۡنَٰهُ وَأَصۡحَٰبَ ٱلسَّفِينَةِ وَجَعَلۡنَٰهَآ ءَايَةٗ لِّلۡعَٰلَمِينَ ١٥\nاس لئے کہ جس نے نوح علیہ السلام کی کشتی نہ دیکھی ہو تو دوسری کشتیو ں کو دیکھ کر نوح علیہ السلام کی کشتی کو یاد کرے اور یہ کہ اللہ تعالیٰ کے حکم سے اسے کیسے بنایا گیا تاکہ اس کے ذریعہ طوفان عظیم سے نوح علیہ السلام اور ہر وہ شخص نجات پاسکے جسے اللہ نے نجات دینی چاہی۔اور اس لئے اس بستی میں رہنے والے اس کشتی کے بارے میں باخبر رہتے ہیں اور یہ خبریں اتنی نقل کی جاتی ہیں کہ وہ متواتر کے درجہ کو پہنچ چکی ہیں۔(ابن عاشور: ۲۰؍۲۲۳)\nنوح علیہ السلام کی کشتی تمام عالم کے لئے نشانی کیسے ہے؟\nإِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَٰنٗا وَتَخۡلُقُونَ إِفۡكًاۚ\nبتوں کے لئے (أوثانا) کا لفظ استعمال کیا جس سے باطل معبودوں کی کثرت کی وجہ سے لوگوں کے ہم و غم کے کثرت کی طرف اشارہ ہے کیونکہ کثرت سے اختلاف لازمی ہے اور اختلاف میں خیر بالکل نہیں ہے۔(البقاعی: ۱۴؍۴۰۷)\nآیت میں (أوثانا) ‘ کا لفظ جمع کے ساتھ کیوں استعمال کیا گیا ہے؟\nفَٱبۡتَغُواْ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُواْ لَهُۥٓۖ إِلَيۡهِ تُرۡجَعُونَ ١٧\n﴿فَٱبۡتَغُواْ﴾اس کلمہ کو باب افتعال کے صیغہ سے لانے میں روزی تلاش کرنے میں محنت مشقت کرنے کی جانب اشارہ ہے کیونکہ عام طور سے الٰہی سنت یہی ہے کہ روزی بلامحنت ومشقت حاصل نہیں ہوتی۔یا تو عبادت اور توکل میں یا تو ظاہری اسباب اپناکر محنت ومشقت کے ذریعہ روزی حاصل کرنے میں۔ وہ شخص عاجز ہے جو اپنے نفس کو خواہشات کے حوالے کرکے اللہ تعالیٰ سے آرزوئیں لگاکر بھروسہ کرے۔ (البقاعی: ۱۴؍۴۱۲-۴۱۳)\nآیت میں اس بات کی طرف اشارہ کیسے ہے کہ روزی کے لئے اسباب اپنانا ضروری ہے؟\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ يُنشِئُ ٱلنَّشۡأَةَ ٱلۡأٓخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٢٠\n(فانظروا کیف بدأ الخلق)یعنی غور کرو اللہ تعالیٰ نے کائنات کی ابتداء کیسے کی،اس کے اندر مخلوقات کی کثرت،ان کی شکلوں میں بے انتہا فرق، طبیعتوں،رنگوں اور زبانوں میں اختلاف کے باوجوداور دیکھوپچھلی قوموں کے ٹھکانوں،گھروں اور ان کے آثار کی طرف کہ کیسے اللہ نے سب کچھ برباد کرکے رکھ دیا تاکہ تمہیں اس کے ذریعہ اللہ کی کمال قدرت کا اندازہ ہوسکے۔ (القرطبی: ۱۷؍۳۵۲)\nاللہ تعالیٰ کی قدرت کے تین آثار کا ذکر کیجئے.\nيُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ ٢١\nیعنی تم اس ٹھکانے کی طرف لوٹوگے جہاں تم پر اس کے عذاب یا رحمت کے احکام جاری ہوں گے اس لئے اس دنیا میں نیکیاں کمالو جو اس کی رحمت کا سبب ہیں اور اس کی نافرمانیوں سے دوررہو جو اس کے عذاب کا باعث ہیں۔(السعدی: ۶۲۹)\nاللہ تعالیٰ کی طرف سے یہ خبردینا کہ سب کو اس کی طرف پلٹ کر جانا ہے۔اس سے ایک مسلمان کو کیا فائدہ ہوتا ہے؟\nيُعَذِّبُ مَن يَشَآءُ وَيَرۡحَمُ مَن يَشَآءُۖ وَإِلَيۡهِ تُقۡلَبُونَ ٢١\nآیت کو سزا کے ذکر سے شروع کیا گیا کیونکہ مخاطب قیامت کے دن اٹھائے جانے کے منکر ہیں جن کے نصیب میں یہ سزا مقدرہوگی۔ (ابن عاشور: ۲۰؍۲۳۲)\nآیت کو عذاب کے ذکر سے کیوں شروع کیا گیا؟\nوَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِ ٱللَّهِ وَلِقَآئِهِۦٓ أُوْلَٰٓئِكَ يَئِسُواْ مِن رَّحۡمَتِي وَأُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ ٢٣\nممکن ہے یہ ناامیدی انہیں آخرت میں ہواور یہ بھی ممکن ہے کہ ان کی دنیوی حالت کو بتایا جارہا ہے کیونکہ کافر اللہ کی رحمت سے ناامیدہوتاہے جبکہ ایک مومن اپنے رب سے پرامید اور خائف رہتاہے۔ (ابن جزی: ۲؍ ۱۵۷)\nاللہ تعالیٰ کی رحمت کے تعلق سے ایک مومن اور ایک کافر کے درمیان کیا فرق ہے؟\nwords\nوَتَخلُقُونَ إِفكًاتم جھوٹ گھڑ لاتے ہو.\nفَابتَغُواتم تلاش کرو.\nبَدَأَ الخَلقَتخلیق شروع کی.\nتُقلَبُونَتم واپس پلٹتے ہو.\nبِمُعجِزِينَعذاب سے بھاگنے والے."],[399,"§العنكبوت\ndeeds\n’’حَسْبِيَ اللّٰهُ وَ نِعْمَ الْوَكِيْلُ‘‘۔میرے لئے اللہ کافی ہے اور وہ بہترین کارساز ہے۔یہ دعاپڑھئے۔بیشک یہ مصیبتوں سے نجات دلاتی ہے۔جس وقت ابراہیم علیہ السلام کو آگ میں ڈالا گیا انہوں نے بھی یہی کہا تھا.\nآپ اپنا جو گناہ جانتے ہیں یا وہ برادوست جو آپ کو برائی کی رغبت دلاتا ہواسے چھوڑدیجئے۔بیشک یہ بھی اللہ کی طرف ہجرت کی ہی ایک قسم ہے.\nوعظ ونصیحت اور عقلی دلائل کے ذریعہ کسی ایسی برائی سے روکئے جسے آپ نے دیکھا ہو.\nguid\nمومن بھروسہ رکھتا ہے کہ جو اللہ کے دین کی مدد کرتا ہے اللہ بھی اس کی حمایت اور مدد کرتا ہے.\nسرکش لوگ جب دلائل سے ہارنے لگتے ہیں تو طاقت استعمال کرنے پر مجبور ہوجاتے ہیں.\nجو اللہ کے لئے کوئی چیز چھوڑتا ہے تو اللہ اسے دنیا اور آخرت میں اس سے بہتر عطاکرتاہے.\nrefl\nفَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُواْ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ\nجب ان پر تمام دلیلیں اور حجتیں قائم ہوگئیں تو انہوں نے (آخری حربہ کے طور پر)اپنے مقام ومرتبہ اور جاہ وسلطنت کو استعمال کیا۔ (ابن کثیر: ۳؍ ۳۹۵)\nظالموں کا طاقت کے استعمال کا سہارا لینا کس بات پر دلالت کرتا ہے؟\nفَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ ٢٤\nآیت میں آپ کو ایک نشانی بتاکر کئی نشانیاں بتائی گئیں کیونکہ وہ نشانی ان سارے لوگوں کے لئے تھی جنہوں نے اس کا مشاہدہ کیا اور اس کے لئے وہ اللہ تعالیٰ کی قدرت اور اس کے رسول کی عزت وکرامت پر دلالت کرتی ہے۔اللہ کے وعدہ کی تصدیق اور اس کے دشمن کو ذلیل کرنے پر دلیل ہے اور یہ کہ چھوٹی اور بڑی تمام مخلوقات اللہ تعالیٰ کی قدرت کے دائرے سے ہٹ کر نہیں ہیں۔(ابن عاشور: ۲۰؍۲۳۵)\nاللہ تعالیٰ کا ابراہیم علیہ السلام کو آگ سے نجات دلانے کو ایک نہیں کئی نشانیاں بتایا گیا۔اس کی وضاحت کیجئے.\nوَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا\nاس میں وہ سب داخل ہیں جوگناہ کا ارتکاب کرنے والوں کی موافقت کرتے ہیں اور گھٹیا لوگوں کا ساتھ دیتے ہیں اور اسے حسن ِمعاشرت اور تہذیب واخلاق میں شمار کرتے ہیں۔یا وہ ایسی حرکتیں اس لئے کرتے ہیں تاکہ انہیں برا اور سخت طبیعت والا نہ کہا جائے۔اللہ کی قسم! اِس وقت یہ بلا عام ہوچکی ہے کہ لوگ اپنے دوستوں اور ساتھیوں کی رضا اور موافقت کی خاطر مالک ِمختار کی رضا او ر خوشنودی کو قربان کردیتے ہیں۔ (البقاعی: ۱۴؍۴۲۴)\nدوستوں اور ساتھیوں کو خوش کرنے کی ایک حد ہوتی ہے۔آیت کی روشنی میں ا س کی وضاحت کیجئے.\nوَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَٰنٗا مَّوَدَّةَ بَيۡنِكُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا\nامام قتادہ رحمہ اللہ سے روایت ہے کہ:دنیا کی تمام دوستیاں قیامت کے دن دشمنی میں بدل جائیں گی سوائے متقیوں کی دوستی کے۔ (الطبری: ۲۰؍۲۵)\nاچھی اور بری صحبت کا فائدہ واضح کیجئے.\nثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يَكۡفُرُ بَعۡضُكُم بِبَعۡضٖ وَيَلۡعَنُ بَعۡضُكُم بَعۡضٗا\nتمام بت اپنی عبادت کرنے والوں سے اور سارے پیر اپنے پیروکاروں سے براء ت کا اظہار کریں گے اور تمام پیروکار اپنے پیروں پر لعنت بھیجیں گے۔ (البغوی: ۳؍ ۴۶۷)\nاگر دنیا میں کسی کی پیروی اللہ کی معصیت پر ہوگی تو قیامت کے دن اس کا کیا نتیجہ ہوگا؟\n۞فَـَٔامَنَ لَهُۥ لُوطٞۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٢٦\nاللہ تعالیٰ نے یہ ذکر نہیں فرمایا کہ اس نے ان کو(ابراہیم علیہ السلام کی قوم کو) ہلاک کردیا تھا بلکہ صرف یہ فرمایا کہ آپ علیہ السلام نے وہاں سے ہجرت کرلی اور اپنی قوم کو چھوڑ گئے۔چنانچہ اگر اللہ تعالیٰ نے عذاب کے ذریعہ ان کو تہس نہس کیا ہوتا تو اس کا ذکر ضرور فرماتا جیسے دیگر جھٹلانے والی قوموں کی ہلاکت کا ذکر فرمایا ہے۔لیکن شاید اس قصہ کا راز یہ ہے کہ خلیل اللہ علیہ السلام مخلوق میں سب سے زیادہ رحیم وشفیق،سب سے زیادہ افضل،سب سے زیادہ بردبار اور سب سے زیادہ جلیل القدر لوگوں میں سے تھے۔آپ نے کبھی اپنی قوم کے لوگوں کے لئے بددعا نہیں کی جیسے دیگر انبیاء کرام علیہم السلام نے بددعا کی۔اس موقف پر یہ واقعہ بھی دلالت کرتا ہے کہ جب فرشتے قوم لوط کو ہلاک کرنے کے لئے آئے اور ابراہیم علیہ السلام سے ملاقات کی تو آپ نے قوم ِلوط کی مدافعت میں ان فرشتوں سے تکرار کی۔ حالانکہ وہ آپ کی قوم نہ تھی اور اصل صورت حال تو اللہ ہی بہتر جانتا ہے۔ (السعدی: ۶۲۹-۶۳۰)\nاللہ تعالیٰ کے اولیاء کی صفتوں میں سے یہ بھی ہے کہ لوگوں پر سب سے زیادہ رحم کرنے والے ہوتے ہیں۔اس نکتہ کو ابراہیم علیہ السلام کے قصہ کی روشنی میں واضح کیجئے.\nوَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ٢٨\nبہت سی برائیوں کے لوگ عادی نہیں ہوتے ہیں جس کی وجہ سے لوگ ان کا ارتکاب عام طور سے نہیں کرتے بلکہ ان سے غافل ہوتے ہیں یہاں تک کہ جب کوئی اس کا ارتکاب کرلیتا ہے اور اس کا مشاہدہ ہوجاتا ہے تب لوگوں کا ذہن اس جانب جاتا ہے اور پھر کچھ لوگوں کو اس برائی کے کرنے کی خواہش ہوجاتی ہے۔ (ابن عاشور: ۲۰؍۲۴۱)\nبرائیوں کو رواج دینے کی سنگینی واضح کیجئے.\nwords\nمَوَدَّةَ بَينِكُماس کی عبادت کی وجہ سے باہم محبت کرتے ہو.\nيَكفُرُوہ اظہار برأت کرتا ہے.\nوَمَأوَاكُمُتمہارا ٹھکانہ.\nمُهَاجِرٌاپنی قوم کا دیار چھوڑ کر شام کی طرف جارہا ہوں.\nأَجرَهُ فِي الدُّنيَااس کا دنیا کا اجر ؛ اس کا ذکر حسن ؛ اور نیک اولاد؛ اور اولاد میں نبوت.\nنَادِيكُمُتمہارے جمع ہونے کی مجلس."],[400,"§العنكبوت\ndeeds\nاپنے آس پاس رہنے والے صالحین کے حالات اور خبریں معلوم کیجئے اور ان کا دفاع کیجئے.\nآپ کا کوئی دوست غم یا بے چینی میں مبتلا ہوتو اس کی تکلیف ہلکی کرنے کی کوشش کیجئے.\nیہ دعا مانگئے: ’’اَللّٰهُمَّ لَا تُؤَاخِذْنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا‘‘۔اے اللہ! ہمارے کم عقلوں کے گناہ پر ہماری گرفت نہ کرنا.\nguid\nایمان اور عمل صالح ہی عذاب سے نجات کے اسباب ہیں۔اگر یہ نہ ہوں تو رشتہ ازدواج کسی فائدے کا نہیں.\nآخرت کو یاد رکھنا اور اس سے ڈرتے رہنا گناہوں سے بچاؤ کا اہم ذریعہ ہے.\nبندوں کو گمراہ کرنے میں شیطان کی چال اس طرح ہے کہ وہ برے اعمال کو اچھا بناکر پیش کرتا ہے۔آپ اس سے خبردار رہئے.\nrefl\nوَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ ٣١\nابراہیم علیہ السلام کے ساتھ اللہ تعالیٰ کی یہ مہربانی تھی کہ قوم ِلوط کی ہلاکت کے بارے میں خبر دینے سے پہلے انہیں خوشخبری دے دی کیونکہ اللہ تعالیٰ کو ابراہیم علیہ السلام کی بردباری معلوم تھی۔ (ابن عاشور: ۲۰؍ ۲۴۲)\nقوم ِلوط کی ہلاکت کے بارے میں خبر دینے سے پہلے خوشخبری دینے کا کیا فائدہ ہے؟\nإِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزٗا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ ٣٤\nعبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ:قوم ِلوط کے اندر فحش کاری کے علاوہ بھی دوسرے گناہ پائے جاتے تھے چنانچہ وہ آپس میں ایک دوسرے پر ظلم کرتے،ایک دوسرے کو گالیا ں دیتے،مرد اور عورتیں ایک دوسرے کا لباس پہن کر مخالف جنس کی مشابہت اختیار کرتے،اس بستی سے ہر گزرنے والے سے ٹیکس وصول کرتے اور ان کی سب سے بری بات یہ تھی کہ وہ اللہ کے ساتھ شرک بھی کرتے تھے۔ اور یہی قوم ہے جس کے اندر سب سے پہلے لواطت اور سحاق جیسی گندی عادتوں نے جنم لیا۔ (القرطبی: ۱۳؍۳۴۲)\nآیت کریمہ کی روشنی میں ملکوں اور بستیوں کی ہلاکت وبربادی کے اسباب پر روشنی ڈالئے.\nوَلَقَد تَّرَكۡنَا مِنۡهَآ ءَايَةَۢ بَيِّنَةٗ لِّقَوۡمٖ يَعۡقِلُونَ ٣٥\nیعنی ہم نے ان کے ساتھ جو بھی سلوک کیا اس میں ہم نے ایک نشانی چھوڑدی جس کے اندر ایسی قوم کے لئے واضح عبرت او ر نصیحت ہے جواللہ تعالیٰ کی دلیلوں کو اچھی طرح سمجھتے ہیں اور اس کی نصیحتوں میں غوروفکر کرتے ہیں۔ (الطبری: ۲۰؍۳۳)\nپچھلی ہلاک شدہ قوموں کے آثار اور ان کی نشانیوں کو باقی رکھنے میں کیا فائدے ہیں؟\nوَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ٣٦\nیعنی کفر نہ کروکیونکہ یہی ہر فساد کی جڑ ہے اور زمین میں تباہی مچانا سب سے بڑا فساد ہے۔ (القرطبی: ۱۶؍۳۶۱)\nسب سے بڑافساد کون ساہے جس سے شعیب علیہ السلام نے منع کیا تھا؟\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ٣٨\nیعنی وسوسہ ڈال کر اور گمراہ کرکے شیطان نے ان کے برے اور کفریہ اعمال کو مزین کردیا۔ یعنی وہ عقل والے ہیں جو غوروفکر اور دلیلوں کی روشنی میں حق وباطل کے درمیان تمیز کرتے ہیں لیکن اس کے باوجود انہوں نے غفلت سے کام لیا اور غور وفکر کرنے کی کوئی ضرورت نہ سمجھی۔(الالوسی: ۱۰؍۳۶۲)\nعقلمندوں کو گمراہ کرنے کے لئے شیطان کن اہم ہتھکنڈوں کا استعمال کرتاہے؟\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ٣٨\n(وکانوا مستبصرین) یعنی اپنی عقل اور بصیرت کی بنیاد پر اپنی پسند سے وہ کفر میں پڑگئے اور یہ معنی بھی بتایا گیا ہے کہ وہ ایمان کی حقانیت سے واقف تھے لیکن ہٹ دھرمی کی وجہ سے وہ کفر پر ڈٹے رہے۔(ابن جزی: ۲؍۱۵۹)\nکیا ہر کفر کی وجہ جہالت ہی ہوتی ہے؟\nوَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِيلِ وَكَانُواْ مُسۡتَبۡصِرِينَ ٣٨\n(کانوا مستبصرین) یعنی دلیلوں کی روشنی میں حق وباطل کوسمجھتے تھے۔امام فَرّاء رحمہ اللہ نے کہا: وہ صاحب ِبصیرت اور عقلمند تھے لیکن ان کی عقلمندی او ر بصیرت نے انہیں کوئی فائدہ نہیں پہنچایا۔(القرطبی: ۱۶؍۳۶۲)\nاگر بندہ اپنے رب کی نافرمانی پر اڑا رہے تو کیا وہ اپنی عقل سے فائدہ اٹھاسکتاہے؟\nwords\nبِالبُشرَىخوشی کی خبر؛ حضرت اسحق علیہ السلام کی بشارت.\nالغَابِرِينَعذاب میں باقی پڑے رہنے والے.\nوَضَاقَ بِهِم ذَرعًااس کا سینہ تنگ ہوگیا۔ ان پر خوف و غم کی وجہ سے.\nرِجزًابہت سخت عذاب.\nوَلاَ تَعثَوااور بہت زیادہ فساد نہ پھیلائیں.\nالرَّجفَةُبہت سخت زلزلہ."],[401,"§العنكبوت\ndeeds\nتکبر سے اللہ کی پناہ مانگئے کیونکہ یہ حق کو ٹھکرانے کے اسباب میں سے ہے.\nقرآن کریم کی کوئی سورت پڑھئے۔یہی وہ وحی ہے جس سے دل منور ہوتے اور دین ودنیا کے معاملات سدھرتے ہیں.\nپنچ وقتہ نمازیں اچھے انداز سے پڑھئے تاکہ وہ آپ کو دل کے ذریعہ کئے جانے والے برے اعمال جیسے کہ محبت اور خوف، اور اعضاء کے ذریعہ انجام پانے والے برے اعمال سے بچائے.\nguid\nاللہ تعالیٰ کا عدل ہی ہے کہ وہ بندے کوصرف اسی گناہ کا عذاب دیگا جو اس نے کیا ہو.\nیاد رکھئے کہ اللہ تعالیٰ کسی پر بھی ظلم نہیں کرتا بلکہ بندہ گناہ کرکے خود ہی اپنے اوپر ظلم کرتا ہے.\nعلم کی فضیلت کوبیان کیاگیا ہے اور یہ کہ اللہ تعالیٰ نے جو مثالیں بندوں کے لئے بیان کی ہیں، ان کا علم فائدہ اٹھانے کے اسباب میں سےہے.\nrefl\nمَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٤١\nامام فراء رحمہ اللہ نے کہا: یہ ایک ایسی مثال ہے جسے اللہ تعالیٰ نے ان لوگوں کے لئے بیان کیاہے جو اسے چھوڑکر ایسے باطل معبودوں کی پرستش کرتے ہیں جو انہیں نفع پہنچاسکتے ہیں نہ نقصان۔جس طرح کہ مکڑی کا گھر اسے نہ تو گرمی سے بچاسکتا ہے او ر نہ سردی سے۔یعنی اگر انہیں پتہ ہوجائے کہ بتوں کی عبادت کرنا بے سود مکڑی کے گھر بنانے کی طرح ہے اور ان کی یہی کمزور مثال ہے تو وہ کبھی بتوں کی عبادت نہ کرتے۔ (القرطبی: ۱۶؍۳۶۳)\nمکڑی کے گھر اور اللہ کے علاوہ دیگر قبروں اور درگاہوں کے درمیان تشبیہ دینے کی کیا وجہ ہے؟اس کی وضاحت کیجئے.\nمَثَلُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ أَوۡلِيَآءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَيۡتٗاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُيُوتِ لَبَيۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٤١\nغرور وتکبر میں مشرکو ں کی تشبیہ مکڑی سے دی گئی ہے اور ان کے اولیاء کی تشبیہ مکڑی کے گھر سے دی گئی ہے کمزوری اور ایسی لاچاری میں جو ضرورت کے وقت کچھ بھی فائدہ نہیں پہنچاسکتے بلکہ معمولی حرکت سے برباد ہوجاتے ہیں۔(ابن عاشور: ۲۰؍۲۵۲)\nمشرکین او ر ان کے اولیاء کو مکڑی اور اس کے گھر سے کیوں تشبیہ دی گئی ہے؟\nوَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ ٤٣\nان مثالوں کی حقیقت اور محاسن صرف کامل عقل والے ہی سمجھ پائیں گے کیونکہ حقیقی علماء یہی ہیں۔اس میں اس بات کی طرف اشارہ ہے کہ جو اِن مثالوں سے فائدہ نہ اٹھائے،وہ جاہل اور بے وقوف ہے۔پھر کیا خیال ہے ان لوگوں کے بارے میں جنہوں نے ان مثالوں میں غوروفکر کرنے اور سمجھنے کی بجائے ان کا مذاق اڑایا۔(ابن عاشور: ۲۰؍۲۵۶)\nقرآنی مثالوں میں غوروفکر نہ کرنے کی کیا سنگینیا ں ہیں؟\nوَتِلۡكَ ٱلۡأَمۡثَٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا يَعۡقِلُهَآ إِلَّا ٱلۡعَٰلِمُونَ ٤٣\nاس کا سبب یہ ہے کہ اللہ تعالیٰ نے قرآن مجید میں جو مثالیں بیان کی ہیں ان کا تعلق بڑے بڑے اوراعلیٰ مقاصداور اہم مسائل سے ہے۔اہل ِعلم جانتے ہیں کہ ضرب المثال بیان کے دیگر اسالیب سے زیادہ اہم ہے کیونکہ اللہ تعالیٰ نے خود اس کا خاص اہتمام کیا ہے اور اپنے بندوں کو ترغیب دی ہے کہ وہ ان میں غوروفکر کریں اور ان کی معرفت حاصل کرنے کی کوشش کریں۔ (السعدی؍۶۳۱)\nمثالوں کے سمجھنے کو اہل ِعلم کے ساتھ کیو ں خاص کردیا گیا؟\nٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِنَ ٱلۡكِتَٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ\nقرآن کی کثرت تلاوت سے معاملات میں بصیرت حاصل ہوتی ہے۔علم کے خزانے کھلتے ہیں۔ایسا نہیں ہے کہ قرآن اپنا فائدہ ایک بار دکھاکر چلاجائے بلکہ قاری جس قدر باربار قرآن کی تلاوت اور اس میں غوروفکر کرتا رہتاہے اسے نئے نئے حکمت کے خزانے ملتے رہتے ہیں۔یہاں تک کہ وہ یہ فیصلہ کرلیتا ہے کہ اس کی حکمتیں اور عجیب وغریب اسرار کبھی ختم ہونے والے نہیں ہیں اور نہ ان کی کوئی حد ہے۔(البقاعی: ۱۴؍۴۴۷)\nتلاوت قرآن ِپاک سے ایک مسلمان حقیقی فائدہ کب اٹھاتا ہے؟\nوَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ\nبعض سلف سے یہ مروی ہے کہ جب وہ نماز کے لئے کھڑے ہوتے تو کانپنے لگتے اور جسم کا رنگ پیلا پڑجاتا۔پوچھا گیا تو جواب دیا کہ میں اللہ کے سامنے کھڑا ہوں جب میں دنیا کے بادشاہوں کے سامنے اس طرح کھڑاہوتا ہوں پھر بادشاہوں کے بادشاہ کے سامنے کیسے کھڑا ہونا چاہئے۔ چنانچہ نماز یقینی طور پر فحش اور منکرکاموں سے روکتی ہے اور جس کی نماز صرف فرض کی ادائیگی پر منحصر ہوجائے اس میں نہ کوئی خشوع ہے نہ اللہ کی یاد ہے او ر نہ فضائل ہیں۔ جوحالت ہماری نمازوں کی ہے، اے کاش ان سے فرض کی ادائیگی ہی ہوجائے۔توایسی نمازیں اپنے پڑھنے والے کو اس کے گھر اسی حالت میں واپس بھیجی جاتی ہیں جس حالت میں وہ مسجد آیا تھا۔ (القرطبی: ۱۶؍۳۶۷)\nنماز کی وہ کون سی قسم ہے جو نمازی کو فحش اور منکر کاموں سے روکتی ہے؟\nوَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِۗ\nایک نمازی جب اپنی نماز خشوع اور خضوع سے پڑھتا ہے اور اللہ پاک کی عظمت کو یاد رکھتا ہے تو یہی چیزاسے فحش ومنکر کاموں سے توبہ پرابھارتی ہے تو گویا نماز ان چیزوں سے روکتی ہے۔ (ابن جزی: ۲؍ ۱۶۰)\nنماز کیسے فحش اور منکر کاموں سے روکتی ہے؟\nwords\nوَمَا كَانُوا سَابِقِينَاللہ کے عذاب سے بچنے والے.\nأَخَذنَا بِذَنبِهِہم نے مذکورین کو ان کے گناہوں کے سبب عذاب میں گرفتار کرلیا.\nحَاصِبًاگیلی مٹی سے بنا ڈھیلا.\nأَوهَنَکمزور.\nوَمَا يَعقِلُهَااور اس کو نہیں سمجھتے."],[402,"§العنكبوت\ndeeds\nآج کچھ ایسی آیتوں کو یاد کیجئے جو پہلے سے یاد نہ رہی ہوں.\nعلمی گفتگو کی مشق کیجئے کہ یہ انبیاء کی سنت ہے، اپنے کسی ایک ساتہی کو چنئے پہر اس سے بڑے ہی اطمینان اور حکمت سے گفتگو کیجئے ، دوران گفتگو عدل وانصاف کا دامن چہوٹنے نہ پائے.\nدعا کیجئے کہ اللہ تعالىٰ آپ کو اپنے احکام وشریعت کو تسلیم و رضا کے ساتھ قبول کرنے والا بنائے.\nguid\nعالم ہر وہ شخص ہے جو اپنے رب کی صحیح طریقے سے عبادت کرنا جانتا ہو گرچہ اسے پڑھنا لکھنا نہ آتا ہو.\nقرآن فصاحت وبلاغت میں انتہا کو پہونچا ہوا ہے جبکہ اس کے لانے والے ہمارے نبی اُمی تھے لکھنا پڑھنا نہیں جانتے تھے.\nاللہ سبحانہ وتعالىٰ کا اس امت پر عظیم احسان ہے کہ اس کی طرف سب سے بہتر کتاب سب سے افضل رسول پر نازل کیا.\nrefl\n۞وَلَا تُجَٰدِلُوٓاْ أَهۡلَ ٱلۡكِتَٰبِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ إِلَّا ٱلَّذِينَ ظَلَمُواْ مِنۡهُمۡۖ وَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ ٤٦\nاہل کتاب سے مباحثہ کرنے میں بہترطریقہ اپنانے کی جو وصیت کی گئی ہے اس کی وجہ یہ ہے کہ اہل کتاب کا اللہ پر ایمان ہے، (قریش کی طرح )وہ اسکے ساتھ شرک نہیں کرتے ہیں، اس لئے وہ حجت ودلیل کو قبول کرنے کی اہلیت رکھتے ہیں نیز ان پر تکبر وعناد کا شبہ نہیں ہے، اور اس لئے بھی کہ انکے دین اور کتاب نے انہیں مباحثہ کا طریقہ سکھا رکھا ہے؛ اس لئے مناسب یہی ہے کہ ان سے دوران گفتگو صرف دلائل پیش کرنے پر اکتفا کیا جائے اور کسی طرح کی سختی سے مطلق پرہیز کیا جائے تاکہ وہ متنفر نہ ہوں۔ (ابن عاشور: ۲۱؍۶)\nاہل کتاب سے مباحثہ کرنے میں بہتر طریقہ اپنانے کی جو وصیت کی گئی ہے اسکی کیا وجہ ہے؟\nوَقُولُوٓاْ ءَامَنَّا بِٱلَّذِيٓ أُنزِلَ إِلَيۡنَا وَأُنزِلَ إِلَيۡكُمۡ وَإِلَٰهُنَا وَإِلَٰهُكُمۡ وَٰحِدٞ\nان کے ساتھ تمہار ا مناظرہ اس طرح نہ ہو کہ کسی بھی آسمانی کتاب یا کسی بھی رسول پرکسی قسم کا قدح وتنقید لازم آئےجیسا کہ مخالف سے مناظرے کے وقت ایک جاہل کرتا ہےکہ اپنے مد مقابل کی ہر چیز پر تنقید کرتا ہے چاہے وہ حق ہو یا باطل، جبکہ یہ صریح ظلم اور علمی گفتگو اور آداب مناظرہ کےخلاف ہے، بلکہ واجب یہ ہے کہ مدمقابل کے باطل پر رد کیا جائے اور اسکے پاس جو حق ہے اسے قبول کیا جائے نہ کہ اسے رد کیا جائے کہ یہ مخالف کا ہے گرچہ وہ کافر ہی کیوں نہ ہو۔ (السعدی: ۶۳۲)\nکافر سے مناظرہ کرنے میں عدل وانصاف اور حکمت کو اپنانا ضروری ہے ، آیت کی روشنی میں اسکی وضاحت کیجئے.\nوَكَذَٰلِكَ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَۚ فَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَٰٓؤُلَآءِ مَن يُؤۡمِنُ بِهِۦۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ ٤٧\nمذکورہ جملے کو اللہ تعالىٰ نے صیغہ مضارع کے ساتھ پیش کیا ہے یہ بتلانے کیلئے کہ مستقبل میں ایسا واقع ضرور ہوگا، یا یہ بتلانے کیلئے یہ لوگ اپنے ایمان کی تجدید ضرور کریں گے، یعنی ان میں جو لوگ مومن ہیں ان کا ایمان باقی رہے گا اور اس طرح دن بدن مومنوں کی تعداد میں اضافہ ہوتا رہے گا۔ (ابن عاشور: ۲۱؍۹)\nآیت کے اندر (یؤمنون) فعل کو صیغۂ مضارع کے ساتھ کیوں لایا گیا ہے؟\nوَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلۡكَٰفِرُونَ ٤٧\nیعنی جن لوگوں کی روش ہی انکار حق اور ہٹ دھرمی ہے، اور اس چیز کو اللہ نے کافروں کے ساتھ منحصر کردیا کہ ان میں سے کسی کا مقصد حق کی اتباع نہیں ہوتا ، ورنہ جس کا مقصد صحیح ہوتا ہےوہ ان آیتوں پر ایمان ضرور لاتاہےکہ یہ واضح دلیلوں پر مشتمل ہیں جنہیں ہر وہ شخص جانتا ہے جس کے پاس کچھ بھی عقل ہو یا جو دل ودماغ کو حاضر کرکے انہیں سنے ۔ (السعدی: ۶۳۳)\nکیا اس قرآن کا انکار وہ شخص کرسکتا ہے جس کی نیت اچھی ہو؟\nبَلۡ هُوَ ءَايَٰتُۢ بَيِّنَٰتٞ فِي صُدُورِ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَۚ وَمَا يَجۡحَدُ بِـَٔايَٰتِنَآ إِلَّا ٱلظَّٰلِمُونَ ٤٩\nحسن بصری نے فرمایا: اس امت کو قرآن کے حفظ کا شرف حاصل ہے جبکہ پہلے کے لوگ اپنی کتابوں کو صرف دیکھ کر پڑھتے تھے، بند کردینے پر انہیں نہیں یاد رہتا سوائے انبیاء کے۔ (القرطبی: ۱۶: ۳۷۶)\nحفظ قرآن کی بڑی فضیلت ہے ، اسکی وضاحت کیجئے.\nأَوَ لَمۡ يَكۡفِهِمۡ أَنَّآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ يُتۡلَىٰ عَلَيۡهِمۡۚ إِنَّ فِي ذَٰلِكَ لَرَحۡمَةٗ وَذِكۡرَىٰ لِقَوۡمٖ يُؤۡمِنُونَ ٥١\nمفہوم یہ ہے کہ یہ کیونکر نشانی طلب کررہے ہیں جبکہ قرآن کریم نبوت کی سچائی پر سب سے بڑی نشانی اور واضح دلیل ہے، نشانیوں کے طلب کرنے میں اسی پر اکتفا کیوں نہیں کرتے! (ابن جزی: ۲؍۱۶۱)\nنزول قرآن کو اس شخص پر بطور رد کے کیسے پیش کرسکتےہیں جس کا گمان یہ ہو کہ اسے نبی - - خود لیکر آئے ہیں ؟\nقُلۡ كَفَىٰ بِٱللَّهِ بَيۡنِي وَبَيۡنَكُمۡ شَهِيدٗاۖ\nاللہ کے تعلق سے میں جو بھی تمہیں خبر دے رہا ہوں وہ اسے اچھی طرح جانتا ہے کہ اسی نے مجھے بھیجا ہے ، اگر میں اس پر جھوٹ بولتا تو وہ مجھ سے ضرور انتقام لیتا۔ (ابن کثیر: ۳؍۴۰۴)\nمحمد صلی اللہ علیہ وسلم کی نبوت کی صداقت پر اللہ کی گواہی کیسے ہوسکتی ہے؟\nwords\nظَلَمُوا مِنهُمحق سے سرکشی کی - اعلان جنگ کیا.\nمُسلِمُونَجھکے ہوئے/ پست اطاعت گزار.\nوَمِن هَؤُلاَءِعرب جو کہ قریش میں سے ہیں.\nلَولاَکیوں نہ.\nآيَاتٌحجتیں اور براہین/ معجزات جیسے حضرت صالح علیہ السلام کی اونٹنی."],[403,"§العنكبوت\ndeeds\nدعا کیجئے کہ اللہ تعالىٰ آپ کو صبر عطا کرے اور اس پر آپ کی مدد کرے.\nاپنے روزانہ اور ہفتے کے کاموں کو اپنی طاقت کے اعتبار سے اوقات میں تقسیم کردیجئے، پھر انہیں دنیا اور آخرت کے کاموں کے لئے دو حصوں میں بانٹ دیجئے ،اس بات پر یقین رکھتےہوئے کہ آپ کے رزق کا ذمہ دار اللہ تعالىٰ ہے نہ کہ وہ آپ کی محنت پر ملے گی.\nغور کیجئے کہ کیسے اللہ تعالىٰ چیونٹیوں اور پرندوں تک روزی پہونچاتا ہے ، پھر دعا کیجئے کہ اللہ تعالىٰ آپ کو بھی حلال، پاک اور بابرکت روزی عطا کرے.\nguid\nاس بات سےڈریں کہ کہیں اللہ کی معصیت کرنے کی حالت میں آپ کو موت نہ آجائے.\nاللہ کی عبادت اور اس کی وحدانیت چھوڑنے پر کوئی بھی عذر قابل قبول نہیں ہے؛ اسی لئے اگر کسی کو کسی شہر میں اس سے روکا جائے تو اس پر واجب ہے کہ اس شہر یا علاقہ کو چھوڑ کر دوسرے شہر یا علاقہ میں چلا جائے.\nآپ رزق کی فکر نہ کریں ، اس کیلئے اللہ کافی ہے.\nrefl\nيَوۡمَ يَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ\nجہنم کی آگ انہیں ہر طرف سے گھیرکر رکھے گی ، اور یہ حسّی عذاب کی انتہا ہے۔ (ابن کثیر: ۳؍۴۰۴)\nعذاب جہنم کو اس طرح کیوں بیان کیا گیا کہ انہیں اوپر اور نیچے ہر طرف سے گھیر کر رکھےگا؟\nوَيَقُولُ ذُوقُواْ مَا كُنتُمۡ تَعۡمَلُونَ ٥٥\nاور یہ معنوی عذاب ہوگا جو ان کے دلوں پر اثر کرےگا۔ (ابن کثیر: ۳؍۴۰۴)\nاس طرح کی بات جہنمیوں سے کیوں کہی جائےگی؟\nيَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّٰيَ فَٱعۡبُدُونِ ٥٦\nاگر کسی جگہ تمہارے رب کی عبادت کرنا محال ہوجائے تو وہاں سے کسی ایسی جگہ ہجرت کرجاؤ جہاں بلاشرکت غیر اللہ کی عبادت ممکن ہو، پس عبادت کی جگہیں بہت کشادہ ہیں اور معبود برحق صرف ایک ہے۔(السعدی: ۶۳۴)\nمومنوں کو اس طرح کی خبر دینے سے کیا مراد ہے کہ اللہ کی زمین بڑی کشادہ ہے؟\nيَٰعِبَادِيَ ٱلَّذِينَ ءَامَنُوٓاْ إِنَّ أَرۡضِي وَٰسِعَةٞ فَإِيَّٰيَ فَٱعۡبُدُونِ ٥٦ كُلُّ نَفۡسٖ ذَآئِقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَيۡنَا تُرۡجَعُونَ ٥٧\nیہاں اللہ تعالىٰ نے موت کا ذکر دنیا اور اسکے پرخطر معاملات کی حقارت کو بتانے کیلئے کیا ہے کہ بعض مومنین یہ سمجھتےہیں کہ اپنے وطن مکہ سے اگر نکل کر دوسری جگہ جائیں گے تو انہیں موت ، بھوک یا اس طرح کے دیگر خطرات کا سامنا ہوسکتا ہے ، اسی لئے اللہ نے دنیا کو حقیر بنا کر پیش کیا ، یعنی تمہیں ہر حال میں مرکر ہماری طرف آنا ہے، اس لئے اللہ کی اطاعت، اسکی طرف ہجرت اور اسکے احکامات کی بجاآوری میں جلدی کرو۔ (القرطبی: ۱۶؍۳۸۲)\nاس شخص کو آپ کیا جواب دیں گے جو یہ کہے کہ اگر میں معصیت کی اس جگہ سے نکل کر چلاجاؤں جہاں میری روزی روٹی کا ٹھکانہ ہے ، تو میرا کیا ہوگا؟\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفٗا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَٰمِلِينَ ٥٨\nیہاں بھی مقصد مومنوں کی ان پریشانیوں کو ہلکا دکھانا ہے جو وہ اللہ کی راہ میں جھیلتےہیں – گرچہ وہ مصیبت موت ہی کی صورت میں کیوں نہ ہو- اللہ کی طرف سے اس انعام وفضل اور ہمیشگی کی جنت کے مقابلے میں جس کا انہیں انتظار ہے۔ (ابن عاشور: ۲۱؍۲۳)\nآیت کی روشنی میں اس بات کو واضح کیجئے کہ مومن جن مصیبتوں کو جھیلتا ہے وہ اس اجر وثواب کے مقابلے بہت ہلکا ہے جس کا اسے انتظار ہے.\nوَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٦٠\nیعنی کتنے ایسے کمزور جاندار ہیں جو اپنی روزی خود حاصل نہیں کرسکتے ، لیکن اللہ تعالىٰ ان کی کمزوری کے باوجود انہیں روزی دے رہا ہے، چنانچہ اس آیت سے مقصد مومنوں کے دلوں کو مضبوط کرنا ہے اس وقت جب انہیں ہجرت کر کے دوسروں کے پاس جانے میں فقروفاقے اور بھوک کا خوف ہو، یعنی جس طرح اللہ تعالىٰ کمزور جانداروں کو رزق دیتا ہے اسی طرح تمہیں بھی رزق دےگا جب تم اپنے علاقے سے ہجرت کرو گے۔ (ابن جزی: ۲؍۱۶۲)\nاس آیت میں مومنوں کے دلوں کیلئے مضبوطی اوران کے نفس کا تزکیہ ہے ، اس کی وضاحت کیجئے.\nوَكَأَيِّن مِّن دَآبَّةٖ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ يَرۡزُقُهَا وَإِيَّاكُمۡۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ٦٠\n(اللہ یرزقہا وإیاکم) رزق کے حریص اور اس کے بارےمیں اللہ پر بھروسہ کرنے والے، زیادتی کے طالب اور قناعت پسند ، حیلہ ساز اور عاجز سب کو اللہ تعالىٰ نے برابر کردیا ہےتاکہ کوئی مضبوط بدن والا یہ نہ سمجھ بیٹھے کہ اسے اس کی رزق اس کےطاقت ور ہونے کی بنیاد پر مل رہی ہے اور کمزور یہ نہ تصور کرے کہ اسے اسکی عاجزی کی وجہ سےکم روزی مل رہی ہے۔ (القرطبی: ۱۶؍۳۸۶)\nکیا کسی کے زیادہ حرص کرنے سے اس کے رزق میں اضافہ ہوجاتا ہے ؟\nwords\nأَجَلٌ مُسَمّىًاللہ کے ہاں ان کے عذاب کا مقررہ وقت.\nيَغشَاهُمُانہیں ڈہانک لیتی ہے؛ گھیر لیتی ہے.\nوَكَأَيِّن مِناور کتنے ہی؟\nفَأَنَّى يُؤفَكُونَوہ کیسے ایمان لانے سے روگردانی کرتے ہیں.\nيَبسُطُوہ وسعت دیتا ہے.\nوَيَقدِرُوہ تنگ کرتا ہے."],[404,"§العنكبوت ، الروم\ndeeds\nامن وامان کی نعمت پر اللہ تعالىٰ کی حمد وثنا بیان کیجئے.\nایسا عمل کیجئے جو اللہ کو پسند ہو گرچہ اس میں مشقت ہی کیوں نہ ہو.\nراہ خدا میں کچھ نہ کچھ خرچ کرتےرہیں.\nguid\nملک ووطن میں امن وامان ایک بہت بڑی نعمت ہےجس کی حفاظت اعمال صالحہ اور اللہ کے احکام کے قیام سے ہوتی ہے.\nمشرکین سے اورخود اپنے نفس سے جہاد کرنے والے کیلئے اللہ کی طرف سے راہ حق کی خوشخبری ہے.\nجان لیں! کامیابی تعداد اور طاقت کے حساب سے نہیں ملتی ، بلکہ یہ صرف اللہ کےہاتھ میں ہے، جسے چاہتا ہے عطا کرتا ہے.\nrefl\nوَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ\nدنیاوی زندگی کا ذکر اسم اشارہ کے ذریعہ کیا گیا اسکی حقارت کو بتانے کیلئے۔ (ابن عاشور: ۲۱؍۳۱)\nآیت کریمہ میں (ہذہ) اسم اشارہ کا کیا فائدہ ہے؟\nوَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ لَوۡ كَانُواْ يَعۡلَمُونَ ٦٤\nیعنی ایسی چیز جو صرف کھیل کود کے لائق ہو، یعنی اللہ تعالىٰ مالداروں کو جو دنیا عطا کرتا ہے وہ جلد ہی ختم اور زائل ہوجائے گی اس کھیل کی طرح جسکی کوئی حقیقت اور پائیداری نہیں ہوتی ۔ بعض نے کہا: دنیا گرچہ تمہارے لئے باقی رہے لیکن تم اس کیلئے باقی نہیں رہ سکتے۔ (القرطبی: ۱۶؍۳۸۷)\nدنیا کی حقیقت ویسے ہی بیان کیجئے جیسے اس کے خالق نے بیان کیا ہے.\nفَإِذَا رَكِبُواْ فِي ٱلۡفُلۡكِ دَعَوُاْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ يُشۡرِكُونَ ٦٥\nکیونکہ جب وہ خشکی میں سفر کرتے تو انہیں ایسا خوف نہیں رہتا جو پورے سفر میں طاری ہو کیونکہ وہ قافلوں کی شکل میں سفر کرتے تھے اور اپنے ساتھ ہتھیار رکھتےتھے، اور ایسے راستوں سے گزرتےتھے جن سے وہ مانوس ہوتے تھے ؛ چنانچہ انہیں وہاں کوئی عام خوف نہیں ہوتا تھا، البتہ دریائی سفر اس سے مختلف ہوتا تھا ؛ کیونکہ وہ دریا کی ہولناکی سے ہمہ وقت خوف میں رہتے تھے جسے انہیں نہ تو افرادی قوت دور کر سکتی تھی اور نہ ہی کسی اسلحہ کی طاقت، ایسی حالت میں نجات کیلئے وہ صرف اللہ کے حضور گڑگڑاتےتھے، بلکہ اس وقت وہ اپنے بتوں کو بھی بھول جاتےتھے۔ (ابن عاشور: ۲۱؍۳۲)\nدریائی سفر کو خوف کے ساتھ خاص کیوں کیا گیا؟\nأَوَ لَمۡ يَرَوۡاْ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنٗا وَيُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ يَكۡفُرُونَ ٦٧\nیعنی ہم نے ان کے لئے ایک پرامن حرم بنا دیا جہاں وہ قید وبند اور قتل وغارت گری سے محفوظ ہیں، اور ہم نے انہیں جس طرح سمندر میں بچایا اسی طرح خشکی میں بھی بچایا، لیکن پھر بھی وہ خشکی میں شرک کرتےہیں اور سمندر میں شرک نہیں کرتے، ان کے انہیں متضاد حالتوں پر تعجب ہے۔ (القرطبی: ۱۶؍۳۸۹)\nآیت کی روشنی میں مشرکین کے متضاد حالات کی وضاحت کیجئے.\nوَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ ٦٩\nابو سلیمان دارانی نے کہا: آیت کے اندر جہاد کا مطلب صرف کافروں سے لڑنا نہیں ہے بلکہ دین کی مدد، باطل پرستوں پر رد ، ظالموں کا قلعہ قمع کرنا بھی مراد ہے، اور عظیم جہاد:بھلائی کا حکم دینا اور برائی سے روکنا ہےاور جہاد یہ بھی ہے کہ نفس سے مجاہدہ کیا جائے بلکہ یہ جہاد اکبر ہے ۔ (القرطبی: ۱۶؍۳۸۹)\nہدایت جیسا عظیم بدلہ کیا صرف کافروں سے لڑائی کرنے کے ساتھ خاص ہے؟\nلِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ\nغلبہ اور فتح فقط اسباب سے نہیں ہوتا بلکہ اس کے لئے قضاوقدر کا اسباب کے ساتھ میل کھانا بھی ضروری ہے ۔ (السعدی: ۶۳۶)\nفارس وروم کے قصے میں اس جملے کو داخل کرنے کا کیا فائدہ ہے؟\nوَيَوۡمَئِذٖ يَفۡرَحُ ٱلۡمُؤۡمِنُونَ ٤\nفارسیوں پر رومیوں کے غالب آنے سے مومن خوش ہوئے ؛ کیوں کہ رومی اہل کتاب تھے، اس طرح وہ اسلام سے زیادہ قریب تھے، جبکہ کفار قریش فارسیوں کے رومیوں پر غالب آنے سےخوش تھے، کیونکہ فارسی اہل کتاب نہیں تھے، اس طرح وہ کفار قریش سے زیادہ قریب تھے۔ (ابن جزی: ۲؍۱۶۴)\nمومن رومیوں کی کامیابی پر خوش کیوں ہوئے جبکہ وہ کافر تھے؟\nwords\nالحَيَوَانُحقیقی کامل اور دائمی زندگی.\nالفُلكِکشتیاں.\nوَيُتَخَطَّفُ النَّاسُوہ جلدی سے قتل یا قید کے لیے اچک لیے جاتے ہیں.\nمَثوىًمسکن / ٹھکانا.\nغُلِبَتِ الرُّومُاہل روم شکست کھاگئے.\nأَدنَى الأَرضِقریبی سر زمین /شام کی فارس کے قریبی زمین.\nبِضعِ سِنِينَبضع کی مدت دس سال سے کم ہوتی ہے۔ یعنی دس سال سے کم عرصہ میں."],[405,"§الروم\ndeeds\nجنت وجہنم کے اوصاف پر کوئی تقریر سنئے.\nاپنے جسمانی اعضاء میں سے کسی ایکمعین عضو پر غور وفکر کریں کہ اللہ نے اسے کیسے بنایا ہے، پھر اس غور وفکر سےحاصل ہونے والے تین فائدے نوٹ کریں.\nدعا کیجئے کہ اللہ تعالىٰ آپ کو نبی کریم صلی اللہ علیہ وسلم کی شفاعت نصیب فرمائے، اور آپ کی حسن اتباع کی توفیق عطا فرمائے.\nguid\nدنیاوی علوم میں سے جو کچھ بہی آپ نے سیکھا ہے اسےاللہ کی عظمت اور اسکی قدرت سے جوڑئیے تاکہ آپ کو اس سے فائدہ ہو.\n(اللہ کی مخلوق میں) غور وفکر کرنا بھی ایک بڑی عبادت ہے ، جسے غور وفکر کی توفیق مل گئی اسے دل کی بیداری نصیب ہوگئی؛ کیونکہ (یہ خصلت) ہمیشہ اسے اس کے رب سے جوڑکر رکھے گی.\nاس عقیدے کو ثابت کیا گیا ہے کہ قیامت کے روز کسی مشرک کے لئے سفارش نہیں ہوسکتی.\nrefl\nوَعۡدَ ٱللَّهِۖ لَا يُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٦\nوعدے کو اللہ کی طرف اضافت کرنے میں یہ اشارہ ہے کہ یہ وعدہ پورا ہوکر رہےگا ؛ کیونکہ اللہ جیسی سچی قادر بے نیاز ذات کے وعدے کو توڑنے کا کوئی سبب نہیں ۔ (ابن عاشور: ۲۱؍۴۸)\nوعدے کو اللہ کی طرف اضافت کرنے کا کیا فائدہ ہے؟\nيَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ غَٰفِلُونَ ٧\nتعجب تو یہ ہے کہ اس قسم کے لوگوں میں بہت سے ایسے ہیں جو دنیاوی معاملات میں اس حد تک ذہین وفطین ہوتےہیں کہ جنہیں دیکھ کر عقلیں حیران ہوجائیں اور دل ششدر ہوکر رہ جائیں۔ دیکھیں انہوں نے ایسی انوکھی انوکھی ایٹمی اور الکٹرانک چیزیں، بری، بحری اور فضائی سواریاں ایجاد کیں جن سے ان کی فوقیت اور برتری عیاں ہے لیکن ساتھ ہی یہی لوگ دینی معاملات میں سب سے زیادہ گئے گزرے ، اپنی آخرت سے سب سے زیادہ غافل اور اپنے انجام کار سے سب سے زیادہ ناآشنا ہیں، صاحب بصیرت انہیں دیکھتے ہیں کہ وہ اپنی جہالت وضلالت میں کس قدر ٹامک ٹوئیاں مار رہےہیں، اور اپنی باطل پرستی میں بھٹک رہےہیں۔ تو یہ سمجھ لیتےہیں کہ سارا معاملہ اللہ کے ہاتھ میں ہے ، بندوں پر سارا فیصلہ اسی کا چلتا ہے، اور توفیق وعدم توفیق اسی کے ہاتھ میں ہے، یہ دیکھ کر اپنے رب سے ڈرتےہیں اور دعا کرتےہیں کہ انہیں عقل وایمان کی جو روشنی نصیب فرمائی ہے اسے پورا کردے یہاں تک وہ اس کے پاس پہنچ جائیں اور اس کے جوار میں نازل ہوجائیں ۔ (السعدی: ۶۳۷)\nہم دنیاوی اور اخروی علم کے درمیان موازنہ کیسے کریں گے؟\nيَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ غَٰفِلُونَ ٧\nحسن بصری رحمہ اللہ نے کہا: ’’کوئی ایک دنیا دار درہم کو اپنے ناخن کے کنارے سے ٹٹول کر اسکا صحیح وزن بتادیتا ہے اور اس میں غلطی نہیں کرتا جبکہ وہ صحیح سے نماز بھی پڑھنا نہیں جانتا،‘‘ اس طرح بہت سارے لوگ پائےجاتےہیں، اور یہ لوگ گرچہ اہل دنیا کے نزدیک بڑے عظیم مانے جاتےہیں لیکن اللہ کے نزدیک ایسے لوگوں کی کوئی وقعت نہیں ہوتی، اسی لئے اللہ تعالىٰ نے اس علم کو (جو صرف ظاہری دنیا تک محدود ہے) حقیر بتایا کیوں کہ صرف ایسا علم رکھنے والے ان چوپایوں کے برابر ہیں جو اپنے لئے نفع بخش چیزوں کا ادراک کرکے مختلف حیلوں سے انہیں حاصل کرتے ہیں، اور نقصان دہ چیزوں کو جان کر انہیں مختلف حربوں سے دور کرتے ہیں ایسے لوگ ان چوپایوں سے کچھ بھی آگے نہیں ہیں۔(البقاعی: ۱۵؍۴۴- ۴۵)\nآخرت کیلئے علم نافع کیا ہے؟\nيَعۡلَمُونَ ظَٰهِرٗا مِّنَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَهُمۡ عَنِ ٱلۡأٓخِرَةِ غَٰفِلُونَ ٧\nیعنی اپنے گزران حال کےبارےمیں جانتےہیں کہ کیسے کمائیں، کیسےتجارت کریں، کب پودا لگائیں، کب کھیتی کریں ، کب کٹائی کریں، کیسے گھر تعمیر کریں اور کیسے زندگی گزاریں، (وہم عن الآخرة ہم غافلون) جبکہ وہ آخرت سے غافل ہیں، یعنی اسے بھولے ہوئےہیں اور اسکے بارےمیں کچھ نہیں جانتے، نہ ہی اس کے بارےمیں کوئی فکر کرتےہیں اور نہ ہی اس کے لئے عمل کرتےہیں۔ (البغوی: ۳؍۴۸۸)\nدنیوی علوم کے دلدادوں کی مذمت کب کی جائیگی؟\nفَمَا كَانَ ٱللَّهُ لِيَظۡلِمَهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٩\n(یظلمون) یعنی وہ نفع حاصل کرنے کے بجائے اپنے نفسوں پر نت نئے ظلم کرتے رہتے ہیں کیونکہ وہ (از خود) اپنی ان عقلوں سے غور نہیں کرتے جنہیں ہم نے ان میں ودیعت کررکھا ہے تاکہ وہ ان سے روشنی حاصل کرکے حق کو باطل سے پہچان سکیں، اور نہ ہی ہدایت کی راہ دکھانے والوں کی مانتے ہیں جب وہ ان کی عقلوں پر پڑے پردوں کو اٹھاتے ہیں، اور نہ ہی گمراہی سے باز آتے ہیں جب راہ دکھانے والے لاجواب کردینے والی نشانیوں سے انہیں بے بس کردیتے ہیں، بلکہ غفلت سے سرکشی کی حد تک جاپہنچتے ہیں۔ (البقاعی: ۱۵؍۵۲)\nعقل کو صحیح طور سے کام میں نہ لاناظلم ہے کیسے؟\nوَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ ٩\nان کے ظلم کے تسلسل اور تکرار کو بتانے کیلئےانکے اپنے نفسوں پر ظلم کرنے کو صیغۂ مضارع سے تعبیر کیا گیا ، اور یہ بھی بتانے کے لئے کہ اللہ نے انہیں ڈھیل دے رکھی تھی پس وہ اپنے رویے سے باز نہیں آئے یہاں تک کہ اللہ نے انہیں اپنی گرفت میں لے لیا۔ (ابن عاشور: ۲۱؍۵۸)\nمشرکین کا اپنے اوپر ظلم کرنے کو صیغۂ مضارع سے تعبیر کرنے کا کیا فائدہ ہے؟\nفَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ فَهُمۡ فِي رَوۡضَةٖ يُحۡبَرُونَ ١٥\n(یحبرون): یعنی ان پر نعمتوں کا اثر ظاہر ہوگا، اور یحیی بن ابی کثیر نے کہا: (فی روضة یحبرون)- سے مراد جنت میں (پرسوز نغمےکا) سننا ہے، اور یہی بات علامہ اوزاعی نے بھی کہاہے کہ جب اہل جنت نغمے سننے کی خواہش کریں گے تو جنت میں کوئی ایسا درخت نہیں بچےگا جو تسبیح وتقدیس کی نغمہ سرائی نہ کرنے لگے۔ (القرطبی: ۱۶؍۴۰۶)\nآیت کی روشنی میں واضح کیجئے کہ جنت میں مومن کا حال کیسا ہوگا؟\nwords\nوَأَجَلٍ مُسَمّىًوقت مقدر جب ختم ہو.\nوَأَثَارُوازراعت و کھیتی کی.\nالسُّوأَىبرائی پر انتہائی قسم کی سزا.\nيُبلِسُعذاب سے نجات پانے سے مایوس.\nيُحبَرُونَوہ اکرام کرتے ہیں و نعمت دیے جاتے ہیں."],[406,"§الروم\ndeeds\n«سُبْحَانَ اللِّٰه بِحَمْدِهٖ» سو مرتبہ پڑھا کریں شام میں، یا صبح میں، یا سہ پہر میں، یا دوپہر میں، یا ان تمام ہی اوقات میں.\nصبح وشام کے جو اذکار یاد نہ ہوں انہیں یاد کرنے میں جلدی کریں.\nاپنے والدین کی (اس بات میں) مدد کریں کہ وہ دونوں ایک دوسرے کو محبت و ہمدردی کے اظہار کے لئے ہدیہ پیش کریں.\nguid\nاصول تربیت میں جزا اور سزا بھی ہے.\nاللہ کا ذکر سارا دن ہوتا ہے.\nپاک ہے وہ ذات جو اختلاف زبان کے باوجود ساری آواز کو سمجھتا ہے، پھر سب کی ضرورتوں کو پوری کرتا اور خطاؤں کو معاف کرتاہے.\nrefl\nيُخۡرِجُ ٱلۡحَيَّ مِنَ ٱلۡمَيِّتِ وَيُخۡرِجُ ٱلۡمَيِّتَ مِنَ ٱلۡحَيِّ\nاس آیت میں اللہ تعالیٰ ذکرکررہا ہے کہ اس نے چیزوں کو ان کے اضداد کے ساتھ پیداکیاہے تاکہ اس کی تخلیق اس کی کمالِ قدرت کی دلیل ہو، جیسے دانے سے پودا اگانا، اور پودے سے دانہ نکالنا، انڈے سے مرغی اور مرغی سے انڈے پیدا کرنا، نطفے سے انسان اور انسان سے نطفے نکالنا، اسی طرح کافر سے مومن اور مومن سے کافر پیدا کرنا۔ (ابن کثیر: ۶؍۲۷۷)\nچیزوں کو ان کے اضداد کے ساتھ پیدا کرنے کے بارے میں اللہ تعالىٰ نے جو خبردی ہے اس سے کیافائدہ حاصل ہوتا ہے؟\nوَمِنۡ ءَايَٰتِهِۦٓ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا لِّتَسۡكُنُوٓاْ إِلَيۡهَا وَجَعَلَ بَيۡنَكُم مَّوَدَّةٗ وَرَحۡمَةًۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَتَفَكَّرُونَ ٢١\n(اللہ نے)میاں بیوی کے درمیان محبت اور رحمت کو پیدا کیا، سو دونوں آپس میں ایک دوسرے سے محبت کرتے ہیں، اور ایک دوسرے پر رحم کرتےہیں، چنانچہ ان دونوں میں سے ہرایک کو اپنے جوڑے سے زیادہ محبوب کوئی اور چیز نہیں ہوتی جبکہ ان دونوں کے درمیان کوئی خونی رشتہ نہیں ہوتا (إن فی ذلک لآیات لقوم یتفکرون) یقینا اس میں نشانی ہے ان لوگوں کیلئے جو اللہ کی عظمت اور اسکی قدرت میں غور وفکر کرتےہیں۔ (البغوی: ۳؍۴۹۱)\nمیاں بیوی کے درمیان محبت و رحمت پیداکرنے میں اللہ تعالىٰ کے عظیم نعمت کی وضاحت کیجئے.\nوَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\nبندوں کے ساتھ اللہ تعالىٰ کی یہ عنایت اور رحمت ہے کہ ان کے درمیان زبان ورنگ کے اختلاف کو مقدر کردیا تاکہ ان میں تشابہ(یکسانیت) پیدا نہ ہوجس سے اضطراب کی صورت پیدا ہو اور بہت سارے مقاصد فوت ہوجائیں۔(السعدی: ۶۳۹)\nغوروفکر کرنے والوں کے نزدیک زبان ورنگ کے اختلاف میں اللہ کی رحمت کا بیان ہے ، اس کی کیا وجہ ہے؟\nوَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\nروئے زمین کے تمام لوگ بلکہ آدم علیہ السلام کی پیدائش سے قیامت تک کے سارے لوگوں کے پاس دو آنکھیں، دو ابرو، ایک ناک، ایک پیشانی، ایک منہ اور دو رخسارہیں، اور ان میں کوئی کسی کے مشابہ نہیں ہے، بلکہ ضرور کسی نہ کسی چیز میں ایک دوسرے سے جداگانہ ہے چال ڈھال میں ہو یا شکل و صورت میں ہو، یا انداز گفتگو میں، چاہے وہ ظاہر ہو یا پوشیدہ۔جوغور وفکر کے وقت ظاہر ہوجاتا ہے، ہر ایک چہرہ بذات خود ایک اسلوب (طرز تخلیق کا نمونہ) ہے اور اس کی ہیئت ایک دوسرے سے جداگانہ ہے۔ (ابن کثیر: ۶؍۲۷۹)\nپیدائشی ہیئت میں انسان کی جومختلف قسمیں ہیں ان پر غور و فکر کرنے سے آپ کو کیا فائدہ حاصل ہوتا ہے؟\nوَمِنۡ ءَايَٰتِهِۦ خَلۡقُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَٱخۡتِلَٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَٰنِكُمۡۚ\n(واختلاف ألسنتکم وألوانکم) زبان منہ میں ہے، جس کے اندر زبانوں(لغات) کا اختلاف پایا جاتا ہے، عربی ، عجمی، ترکی، رومی وغیرہ، اور رنگ کا اختلاف شکل وصورت میں ہے، جیسے گورا، کالا، سرخ ، کہ جسے بھی آپ دیکھ لیں اسے دوسرے سے فرق کرلیں، اور ان ساری چیزوں میں نہ تو نطفوں کا عمل دخل ہے اور نہ ہی والدین کا ، تو ضروری ہے کہ ان کا فاعل(ان سارے امور کو انجام دینے والا) کوئی ہو ، اوروہ اللہ تعالىٰ ہے، اور یہی مدبر باری کی سب سے بڑی دلیل ہے(یعنی اس کائنات کو پیداکرنے والا اور اس کے نظام کو چلانے والا کوئی ہے اور وہ اللہ ہے)۔(القرطبی: ۱۶؍۴۱۳)\nزبان ورنگ کا اختلاف کس چیز پر دلالت کرتاہے؟\nوَمِنۡ ءَايَٰتِهِۦ مَنَامُكُم بِٱلَّيۡلِ وَٱلنَّهَارِ وَٱبۡتِغَآؤُكُم مِّن فَضۡلِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَسۡمَعُونَ ٢٣\nفضلِ الٰہی کو تلاش و جستجو کے ساتھ جوڑنے میں اس بات کی طرف اشارہ ہے کہ بندہ یہ نہ سمجھے کہ رزق اس کی ذات اور اسکی عقلمندی سے حاصل ہوتی ہے، بلکہ یہ سمجھے کہ سب کچھ اللہ کے فضل وکرم سے حاصل ہوتا ہے۔(الألوسی: ۱۱؍۳۳)\nاللہ کے قول: (وابتغاؤکم من فضلہ)میں فضلِ الٰہی کو تلاش و جستجو سے جوڑنے سے کیا فائدہ حاصل ہوتا ہے؟\nوَمِنۡ ءَايَٰتِهِۦ يُرِيكُمُ ٱلۡبَرۡقَ خَوۡفٗا وَطَمَعٗا وَيُنَزِّلُ مِنَ ٱلسَّمَآءِ مَآءٗ فَيُحۡيِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ ٢٤\nمذکورہ نشانیوں سے فائدہ اٹھانے کو اصحاب عقل سے جوڑ دیا دیا گیا ؛ کیونکہ مذکورہ نشانیوں میں جو دلائل اور حکمتیں ہیں ان کو وہی عقل مستقیم سمجھ سکتی ہے جو ہٹ دھرمی اور بغض وعناد جیسی بیماریوں سے پاک ہو۔ (ابن عاشور: ۲۱؍۷۹)\nآیت کریمہ کے اندر فائدہ اٹھانے کو اہل عقل کے ساتھ کیوں خاص کردیا گیا ہے؟\nwords\nمُحضَرُونَمقیم.\nتُظهِرُونَتم ظہر کے وقت میں داخل ہوتے ہو.\nلِلعَالِمِينَجمع عالم / علم و بصیرت والے.\nوَابتِغَاؤُكُم مِن فَضلِهِتمہارا دن کے وقت اس سے روزی طلب کرنا.\nخَوفًا وَطَمَعًاتم ڈرتے ہوئے بجلیوں سے ؛ اور امید رکھتے ہو بادل کی."],[407,"§الروم\ndeeds\nاپنی نمازوں کو اس ثابت شدہ دعا سے شروع کیجئے: ﴿وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفًاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ﴾ رواہ مسلم (ترجمہ: میں یکسو ہوکر اپنا رخ اس کی طرف کرتا ہوں جس نے آسمانوں اور زمین کو پیدا کیا، اور میں شرک کرنے والوں میں سے نہیں ہوں).\nنماز باجماعت خشوع اور اطمینان کےساتھ ادا کیجئے تاکہ آپ ایمان کی (عملی) تصدیق پیش کرسکیں.\nاللہ کی پناہ مانگئے، اور اپنے آس پاس کے لوگوں کو مومنوں کی جماعت میں توڑ پھوڑ سے ڈرائیے.\nguid\nآپ کے ارد گرد ساری کائنات اللہ کی تابعدارو فرمانبردار ہے لہذا آپ اعراض کرنے والے غافل بندوں میں سے نہ بنیں.\nاللہ تعالىٰ نے اپنی کتاب میں اکثر یہ بتایا ہے کہ اعراض کرنےوالوں کے اعراض کا سبب خواہشات نفس کی پیروی رہتی ہے.\nمشرکین کی عادت اختلاف اور تفرقہ بازی ہے، لہذا ان کی مشابہت اختیار کرنے سے بچیں.\nrefl\nوَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ ٢٧\n(اللہ تعالیٰ کی) بہترین اور اعلیٰ صفات میں اسکی عزت اور حکمت بھی ہے، اور یہاں انہیں دونوں صفتوں کا بطور خاص ذکر کیا گیا ؛ کیونکہ انہیں دونوں صفتوں کے آثار اس مقصد پر ظاہر ہوتےہیں جس پر گفتگو ہورہی ہے، وہ مقصد ہے: مخلوق کی پہلی پیدائش اور پھر اسکا دوبارہ پیدا کرنا، چنانچہ عزت مکمل بے نیازی کا تقاضہ کرتی ہے؛یعنی مکمل طور پر بےنیاز ذات قدرتِ کاملہ کی مالک ہو، اور حکمت شامل و کامل علم کا تقاضہ کرتی ہے۔ (ابن عاشور: ۲۱؍۸۴)\nآیت کریمہ میں بطور خاص (العزیز الحکیم) جیسی دونوں صفتوں کا ذکر کیوں کیا گیا؟\nوَهُوَ ٱلَّذِي يَبۡدَؤُاْ ٱلۡخَلۡقَ ثُمَّ يُعِيدُهُۥ وَهُوَ أَهۡوَنُ عَلَيۡهِۚ\n(وہو) یعنی مخلوق کی موت کے بعد اسے دوبارہ پیدا کرنا، (أہون علیہ) اللہ پر زیادہ آسان ہے ، پہلی پیدا ئش کے مقابلے میں، اور یہ لوگوں کے ذہن وعقل کے اعتبار سے ہےکہ جب وہ پہلی پیدائش پر قادر ہے جس کا تم اقرار کرتے ہو ، تو اسے دوبارہ پیدا کرنےپر وہ کہیں زیادہ قادر ہےاور یہ اسکے لئے بہت آسان ہے۔ (السعدی: ۶۴۰)\nقرآن کے اندر (باطل عقائد و نظریات کے) رد کے لئے عقلی اسلوب استعمال کیا گیا ہے آیت کی روشنی میں اس کی وضاحت کریں.\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ ٢٨\n(اللہ تعالیٰ نے آیتوں اور نشانیوں کو کھول کھول کر عقلمند قوم کے لئے بیان کردیا ہے) اور عقلمند قوم وہ ہے جو ہٹ دھرمی اور اعراض جیسی بری خصلتوں سے پاک و صاف ہو، اور اپنے کمال عقل کے سبب حق اور حقائق کی متلاشی ہو، سو ان واضح دلائل سے مومنوں کے یقین میں اضافہ ہوتا ہے، اور وہ لوگ ایمان سے مشرف ہوتے ہیں جو اب تک غفلت میں پڑے تھے اور جن پر مشرکین کی گمراہیاں رواج پاچکی تھیں پھر ان جیسے واضح دلائل سے وہ گمراہیاں ان سے کافور ہوگئیں… اور اس میں بطورکنایہ یہ بات بھی ہے کہ جو شرک میں نہایت سخت ہیں وہ عقلمندوں میں سے نہیں ہیں اور نہ ان لوگوں میں سے ہیں جو (ان واضح نشانیوں سے) فائدہ اٹھاسکتے ہیں۔ (ابن عاشور: ۲۱؍۸۷)\nمذکورہ بالا فکری گوشے کی روشنی میں عقلمندوں کے چند اہم اوصاف بیان کیجئے.\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡقِلُونَ ٢٨\nالبتہ جو عقل سے عاری ہو اس کے سامنے اگر ساری نشانیاں بیان کردی جائیں اور سارے دلائل پیش کردئیے جائیں تو ان کے پاس ایسی عقل ہی نہیں جو ان بیان کردہ امور کو جان بوجھ سکے، اور ایسا دماغ ہی نہیں جو ان واضح باتوں کو سمجھ سکے، پس عقل ودماغ کے مالک ہی اس بات کے مستحق ہیں کہ اس طرح کا کلام ان کے سامنے پیش کیا جائے اور انہیں خطاب کیا جائے۔ (السعدی: ۶۴۰)\nخطاب کو عقلمندوں کے ساتھ ہی کیوں خاص کیاگیا؟\nفَأَقِمۡ وَجۡهَكَ لِلدِّينِ حَنِيفٗاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ ٣٠\nاسلام کی خوبی یہ بیان کی گئی کہ وہ اللہ کی فطرت ہے (جس پر اس نے لوگوں کو پیدا کیا ہے) اس کا مطلب یہ ہے کہ اس میں سارے اعتقاد کی اصل عقلی فطرت کے مطابق ہوتی ہے، البتہ جہاں تک اسکے احکام اور فروعی مسائل کا تعلق ہے تو وہ بھی یا تو فطری امور ہوتے ہیں یعنی وہ عقل کے موافق ہوتے ہیں کہ عقل اسے سمجھتی ہے اور قبول کرتی ہے یا عقل کی درستگی کے لئے ہوتے ہیں جو فطرت کے منافی (مخالف) نہیں ہوتے۔(ابن عاشور:۲۱؍۹۱)\nاسلام کو فطرت سے متصف کرنے کا کیا معنی ہے؟\n۞مُنِيبِينَ إِلَيۡهِ وَٱتَّقُوهُ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَلَا تَكُونُواْ مِنَ ٱلۡمُشۡرِكِينَ ٣١ مِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۢ بِمَا لَدَيۡهِمۡ فَرِحُونَ ٣٢\n(یہ مشرکین کی بری حالت کا بیان ہے جس سے مسلمانوں کو ڈرانا مقصود ہے کہ )جب اختلافِ اجتہاد کے تقاضے کے تحت دینی معاملات میں ان کے درمیان اختلاف ہوجائے یا مفادات کے اختلاف کے سبب آراء اور سیاسی امور میں اختلاف ہوجائے تو انہیں ہوشیار رہنا چاہئے کہ یہ اختلاف انہیں یہاں تک نہ پہنچادے کہ وہ مختلف ٹولیوں میں بٹ جائیں جو ایک دوسرے کے دشمن ہوں۔(ابن عاشور: ۲۱؍۹۶)\nاہل کتاب کے اختلاف کی مذمت سے مسلمانوں کو کیا فائدہ حاصل ہوتا ہے؟\nمِنَ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗاۖ كُلُّ حِزۡبِۢ بِمَا لَدَيۡهِمۡ فَرِحُونَ ٣٢\n﴿شِيَعًا﴾ باہم عہد وپیمان کرنے والے ایسے گروہ کہ ان میں سے ہرگروہ اپنے ہم مذہب کی تائید و حمایت کرتا ہے ہر اس شخص کے خلاف جو ان کا مخالف ہو، حتی کہ ایک دوسرے کو کافر قرار دیا، اور (مخالف کے) خون و مال کو حلال سمجھا سو اس سے قطعی طور پر پتہ چلاکہ وہ تمام کے تمام گروہ راہ حق پر نہیں ہے۔ (فرحون) خوش ہیں اس گمان میں کہ دوسروں کو چھوڑ کروہی حق کو پانے میں کامیاب ہیں۔ (البقاعی: ۱۵؍۹۰-۹۱)\nآیت کی روشنی میں اللہ کے دین میں اختلاف کے خطرے کی وضاحت کیجئے.\nwords\nفِطرَةَ اللهِاللہ کا دین / مراد اسلام.\nفَطَرَ النَّاسَ عَلَيهَااس نے لوگوں کو پیدا کیا اس پر؛ طبیعت دی.\nالقَيِّمِوہ سیدھا راستہ جو اللہ تعاليٰ تک پہنچائے.\nفَرَّقُوا دِينَهُماپنے دین کو بدل ڈالا/ کچھ مانا کچھ نہ مانا.\nشِيَعًافرقے اور گروہ."],[408,"§الروم\ndeeds\nاپنے کسی رشتے دار کی زیارت کیجئے یا اس سے فون پر بات کیجئے اور اسکی خیریت معلوم کرکے اطمینان حاصل کیجئے.\nکسی مسکین پر صدقہ کیجئے، یا اسے اپنے گھر بلاکر اسکی اچھی طرح مہمان نوازی کیجئے.\nایک میسیج بھیجئے جس میں سود یا دوسری سماجی برائیوں کے نقصانات کا ذکر کیجئے.\nguid\nرزق کی کشادگی اور قلت میں اللہ کی جو حکمت اور تدبیرہے اسے خصوصی طور پر مومن ہی سمجھتےہیں.\n(اللہ کے راستے میں) خرچ کرنے میں اخلاص کو لازم پکڑیں کیونکہ ہر صدقہ مقبول نہیں ہوتا.\nجب آپ دیکھیں کہ کوئی مصیبت آن پڑی ہے یا کوئی آفت نازل ہوئی ہے تو کوئی ایسا گناہ یاد کریں جس کا ارتکاب آفت و مصیبت سے پہلے کیاگیا ہے.\nrefl\nوَإِذَا مَسَّ ٱلنَّاسَ ضُرّٞ دَعَوۡاْ رَبَّهُم مُّنِيبِينَ إِلَيۡهِ ثُمَّ إِذَآ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِيقٞ مِّنۡهُم بِرَبِّهِمۡ يُشۡرِكُونَ ٣٣\nیعنی ان کافروں کو جب کوئی بیماری یا مصیبت لاحق ہوتی ہے تو اپنے رب کو پکارتےہیں، یعنی اس مصیبت کو ختم کرنے کیلئےاللہ واحد کی طرف متوجہ ہوکر صرف اسی سے مدد طلب کرتے ہیں اور بتوں کو چھوڑ دیتےہیں، کیونکہ انہیں یہ یقین ہوتاہے کہ وہ مصیبتوں کو دور نہیں کرسکتے (ثم إذا أذاقہم منہ رحمة) پہر جب وہ انہیں اپنی رحمت سے نوازتا ہے یعنی عافیت اور نعمت عطاکرتا ہے، (إذا فریق منہم بربہم یشرکون) اس وقت ان میں ایک گروہ اپنے رب کےساتھ شرک کرنے لگ جاتاہے، یعنی عبادت میں اللہ کے ساتھ اوروں کو بھی شریک کرنے لگتا ہے۔(القرطبی: ۱۶؍۴۳۳)\nاس شخص کی اللہ نے مذمت کیسے کی ہے جو مصیبت میں اسے یادکرتا ہے اور نعمت میں بھول جاتاہے؟\nوَإِذَآ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةٗ فَرِحُواْ بِهَاۖ وَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ٣٦\nدیکھیں یہاں(رحمت کے سلسلے میں) کیسے (وإذا) کہا جبکہ تکلیف کے بارے میں (وإن تصبہم سیئة) فرمایا؛ کیونکہ (وإذا) کا استعمال اس وقت ہوتا ہے جب شرط کا واقع ہونا قطعی ہو، برخلاف (إن) کے کیونکہ اس کا استعمال اس وقت ہوتا ہے جب شرط کا واقع ہونا مشکوک ہو، سو اس میں اس بات کی طرف اشارہ ہے کہ وہ خیرجس سے اللہ اپنے بندوں کو نوازتا ہے شر سے بہت زیادہ ہے۔(ابن جزی: ۲؍۱۶۹)\nآیت اس بات پر کیسے دلالت کرتی ہے کہ وہ خیر جس سے اللہ اپنے بندوں کو نوازتا ہے، شرسے بہت زیادہ ہے؟\nوَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ٣٦\nجب گناہ کے سبب مصائب آرہے ہیں، اور حالت یہ ہے کہ مصیبتوں میں مبتلا ہونے والے ان گناہوں سے باز نہیں آرہے ہیں جن کے سبب وہ سزا سے دوچار ہوئے، (اور رحمتِ الٰہی سے ناامید بھی ہورہے ہیں) اس لئے اللہ تعالیٰ نے انہیں تنبیہ کرتے ہوئے اور ان کی ناامیدی پر نکیر کرتے ہوئے فرمایا (بما قدمت أیدیہم) یعنی یہ مصیبت ان کے ہاتھوں کی کرتوت کی وجہ سے ہے۔(البقاعی: ۱۵؍۹۵)\nگناہوں کے بعض آثار کا تذکرہ کیجئے.\nوَإِن تُصِبۡهُمۡ سَيِّئَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ إِذَا هُمۡ يَقۡنَطُونَ ٣٦\nفرمان باری: (بما قدمت أیدیہم) سے اس بات کی تنبیہ مقصود ہے کہ لوگوں کو دنیا میں جو مصیبت لاحق ہوتی ہے اس کا سبب خود ان کے کرتوت ہوتے ہیں جنہیں اللہ تعالىٰ نے نتائج و اثرات کا موثرسبب بنایا ہے، جن کے رازوں اور باریکیوں کو صرف اللہ تعالىٰ ہی جانتا ہے ، لہٰذا لوگوں کو چاہیئے کہ وہ اپنا محاسبہ کریں اور مصیبتوں کے لاحق ہونے کے اسباب سے بچیں اور اپنی کوتاہیوں کی تلافی کیلئے عمل کریں، یہی برائیوں اور مصیبتوں سے نجات کا بہتر ذریعہ ہے۔ اور ناامیدی سے زیادہ کارگر طریقہ ہے اوریہ قرآن کریم کے آداب میں سے ایک عمدہ ادب ہے ، ارشاد باری ہے﴿مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَ﴾ [سورۂ نساء: ۷۹] (تمہیں جو بھلائی ملتی ہے وہ اللہ کی طرف سےہے، اور تمہیں جو مصیبت آتی ہے وہ تمہاری طرف سے ہے) (ابن عاشور: ۲۱؍۱۰۱)\nانسانوں پر دنیا میں لاحق مصیبتوں کا سبب کیا ہے؟\nوَمَآ ءَاتَيۡتُم مِّن رِّبٗا لِّيَرۡبُوَاْ فِيٓ أَمۡوَٰلِ ٱلنَّاسِ فَلَا يَرۡبُواْ عِندَ ٱللَّهِۖ وَمَآ ءَاتَيۡتُم مِّن زَكَوٰةٖ تُرِيدُونَ وَجۡهَ ٱللَّهِ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُضۡعِفُونَ ٣٩\nامام شعبی نے کہا: آیت کا معنی یہ ہے جب انسان اپنی دنیا میں فائدہ اٹھانے کی غرض سے کسی آدمی کی خدمت کرتا ہےاور اس کی اطاعت بجالاتا ہے تو یہ نفع جو مخدوم اپنے خادمین کو بطورصلہ دیتا ہےاللہ کے یہاں نہیں بڑھتا ہے۔ (القرطبی: ۱۶؍۴۳۸)\nاگر انسان کسی کی خدمت کرکے دنیوی بدلہ چاہتا ہے تو کیا اس پر اسے ثواب ملےگا؟\nظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ لِيُذِيقَهُم بَعۡضَ ٱلَّذِي عَمِلُواْ لَعَلَّهُمۡ يَرۡجِعُونَ ٤١\nپاک ہے وہ ذات جس نے (بعض گناہوں کے سبب) کچھ مصیبت اور سزا دیکرانعام و احسان کیا ، ورنہ اگر تمام گناہوں کا مزہ چکھاتا تو زمین میں کوئی جاندار نہ بچتا۔ (السعدی: ۶۴۳)\nمصیبت میں بھی اللہ کی نعمت اور اس کا احسان ہے، کیسے؟\nظَهَرَ ٱلۡفَسَادُ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَيۡدِي ٱلنَّاسِ\nخشکی میں بگاڑ (مختلف صورتوں میں) ظاہرہوتا ہے جیسے قحط سالی، فتنے اور اس جیسی دیگر مصیبتیں اور دریامیں بگاڑ (مختلف صورتوں میں) ظاہرہوتا ہے جیسے غرقابی، شکار کی کمی، تجارت کی مندی اور اس طرح کی دوسری پریشانیاں ، اور یہ سب انسانوں ہی کے کرتوت اور اسکے کفر ومعصیت کی وجہ سے ہوتا ہے۔(ابن جزی: ۲؍۱۶۹)\nبگاڑ کے ظہور کی کیا نشانیاں ہیں؟ اور اسکا کیا سبب ہے؟\nwords\nيَقنَطُونَوہ آزمائش ختم ہونے سے نا امید ہو جاتے ہیں.\nيَبسُطُوہ وسعت دیتا ہے.\nوَيَقدِرُاور وہ تنگ کرتا ہے.\nرِبًاحرام سود کی غرض سے قرض.\nلِيَربُوَتاکہ وہ بڑھے."],[409,"§الروم\ndeeds\nاستقامت اور اسکی اہمیت پر ایک پیغام لکھئے اوراسے اپنے دوستوں کو بھیجئے.\nجب کوئی آندھی یا بدلی دیکھیں تو حدیث میں وارد یہ دعاء پڑھیں: (اَللّٰهُمَّ إِنِّيْ أَسْئَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيْهَا وَخَيْرَ مَا أُرْسِلَتْ بِهٖ، وَأَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ مَا فِيْهَا وَشَرِّ مَا أُرْسِلَتْ بِهٖ) (اے اللہ! میں تجھ سے اس کی خیر مانگتا ہوں، اور جو کچھ اس میں ہے اس کی خیر کا طلب گار ہوں، اور جو خیر اس کے ساتھ بھیجی گئی ہے اسے چاہتا ہوں۔ اور میں اس کے شرسے تیری پناہ چاہتا ہوں، اور جو کچھ اس کے اندر ہے اس کے شرسے بھی، اور جو شر اس کے ساتھ بھیجاگیا ہےاس سے بھی.\nآپ پراور آپ کے اردگردکے لوگوں پر اللہ کی رحمت کے جوآثار ہیں ان میں سے تین پر غور وفکر کریں پھر اس پر اللہ تعالیٰ کا شکریہ بجالائیں.\nguid\nبدلہ کرتوت کے جنس سے ملتا ہے (جیسی کرنی ویسی بھرنی).\nجان لیں کہ اللہ تعالیٰ کا ثواب مومن بندوں کے لئے ان کے عمل سے بہت بڑا اور زیادہ ہے کیوں کہ وہ اپنے فضل اور کشادہ رحمت سے بدلہ دیتا ہے.\nمایوسی سے دور رہیں؛ کیونکہ اللہ اپنے دین کی مدد کرکےرہےگا.\nrefl\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ\nپچھلی امتوں کے انجام کار پر غور وفکر کرنے کیلئے زمین کے اندر سیر وسیاحت کا جو حکم ہے اس میں بدنی سیاحت کے ساتھ قلبی سیاحت بھی داخل ہے ۔(السعدی: ۶۴۳)\nغور وفکر کیلئےزمین میں سیاحت کرنا کیا صرف سفر پر منحصر ہے؟\nفَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ ٤٢\nچنانچہ ان(سابقہ معذب اقوام) کے کرتوتوں جیسا کرنے سے بچیں (ورنہ) آپ لوگوں کے ساتھ بھی ان کے جیسا ہی سلوک کیاجائے گا ؛ کیونکہ اللہ کا عدل اور اسکی حکمت ہرزمانے اور ہرجگہ کیلئےہے۔ (السعدی: ۶۴۳)\nپچھلی امتوں کے انجام کار میں غور وفکر کرکے ایک انسان کیا فائدہ اٹھاتا ہے؟\nقُلۡ سِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِينَ ٤٢\nفرمانِ الٰہی (کان أکثرہم مشرکین) جملہ استئنافیہ ہے (یعنی نیاجملہ ہے) ، اس بات پر دلالت کرنے کیلئے کہ صرف شرک ہی تمام لوگوں کی بربادی کا سبب نہیں تھا، بلکہ وہ اکثر لوگوں کی بربادی کا سبب تھا، اور شرک سے کمترگناہ بھی کچھ لوگوں کی بربادی کا سبب تھا۔ اور یہ بھی ممکن ہے (کہ یہ کہاجائے) کہ یہ اس بات پر دلالت کرنے کے لئے ہے کہ ان کا برا انجام ان کے درمیان شرک کے پھیلنے اور اس کے غالب ہونے کی وجہ سے ہے پس اس میں شرک کی سنگینی کا بیان ہے کہ یہ اتنا بڑا فتنہ ہے جو خاص طور پر صرف ظالموں کو لاحق نہیں ہوتاہے (بلکہ دوسرے بھی اس کی لپیٹ میں آتے ہیں)۔ (الألوسی: ۱۱؍۴۹)\nپچھلی امتوں کی ہلاکت کے کیا اسباب ہیں؟اور ان میں سب سے بڑا سبب کیا ہے؟\nإِنَّهُۥ لَا يُحِبُّ ٱلۡكَٰفِرِينَ ٤٥\n(اللہ تعالیٰ کافروں سے محبت نہیں کرتا ہے)اس کے باوجود وہ ان کے ساتھ بھی انصاف کرتاہے ظلم نہیں کرتا۔(ابن کثیر: ۳؍۴۲۰)\nکیا عدم محبت ظلم کا متقاضی ہے؟\nوَمِنۡ ءَايَٰتِهِۦٓ أَن يُرۡسِلَ ٱلرِّيَاحَ مُبَشِّرَٰتٖ وَلِيُذِيقَكُم مِّن رَّحۡمَتِهِۦ\nچنانچہ اللہ تعالىٰ اپنی رحمت کی بارش تم پر نازل کرتا ہے جس سے زمین اور بندوں میں زندگی کی لہردوڑجاتی ہے، اور اسکی رحمت کا مزہ تمہیں ملتا ہے جس سے تمہیں معلوم ہوتا ہے کہ اسکی رحمت ہی بندوں کے لئے سامان نجات اور روزی کا سبب ہے تو تمہارے اندر ان نیک اعمال کو بکثرت انجام دینے کا شوق پیداہوتا ہے جو رحمت کے خزانوں کوکھول دینے والے ہیں۔ (السعدی: ۶۴۳)\nایک مسلمان جب اللہ تعالىٰ کی رحمت کا مزہ پاتا ہے تو اس پر کیسا اثر ہوتا ہے؟\nوَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَآءُوهُم بِٱلۡبَيِّنَٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِينَ أَجۡرَمُواْۖ وَكَانَ حَقًّا عَلَيۡنَا نَصۡرُ ٱلۡمُؤۡمِنِينَ ٤٧\n(وکان حقًا علینا نصر المؤمنین) مومنوں کی مدد اور عذاب سے بچانا ہمارے اوپر حق ہے، اس کےاندر نبی کریم صلی اللہ علیہ وسلم کو یہ خوشخبری دی گئی ہے کہ آخرکار کامیابی اور دشمنوں پر غلبہ آپ ہی کو ملےگا۔ حسن بصری رحمہ اللہ نے کہا: امتوں پر جو عذاب آتاتھا اس عذاب سے اللہ نے رسولوں کے ساتھ ان پر ایمان لانے والوں کو بچالیا۔(البغوی: ۳؍۵۰۰)\nکیا اہل باطل کے طویل تسلط سے مومنوں کو مایوس ہوجانا چاہیئے؟ آیت کی روشنی میں اس کی وضاحت کریں.\nوَإِن كَانُواْ مِن قَبۡلِ أَن يُنَزَّلَ عَلَيۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِينَ ٤٩ فَٱنظُرۡ إِلَىٰٓ ءَاثَٰرِ رَحۡمَتِ ٱللَّهِ كَيۡفَ يُحۡيِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ ذَٰلِكَ لَمُحۡيِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ٥٠\n(من قبلہ) کو مکرر لایا گیا ہے تاکید کیلئے، اور تاکہ یہ بتایا جائے کہ انسان کے دل جلدی سے کیسے مایوسی سے خوشی کی طرف پلٹ جاتےہیں ۔ (ابن جزی: ۲؍۱۷۰)\n(من قبل)،کے لانے کے بعد اسی آیت میں پھر (من قبلہ) لانے میں کیا حکمت اور راز ہے؟\nwords\nلاَّ مَرَدَّ لَهُکوئی ایک اس کے رد پر قادر نہیں.\nيَصَّدَّعُونَمخلوقات کو متفرق گروہ کردیتے ہیں.\nيَمهَدُونَوہ جنت میں اپنے ٹھکانے تیار کرتے ہیں.\nفَتُثِيرُوہ حرکت میں آتا ہے؛ منتشر ہوتا ہے.\nكِسَفًامتفرق ٹکڑے."]])